window.CARDS_L={"Rigveda 3.62.10": ["ઋગ્વેદ 3.62.10", "ગાયત્રી મંત્ર", "અમે એ સવિતા દેવના શ્રેષ્ઠ, પવિત્ર તેજનું ધ્યાન કરીએ છીએ. તેઓ અમારી બુદ્ધિને સન્માર્ગ તરફ પ્રેરે.", "આ ધન કે વસ્તુઓની નહીં, શુદ્ધ અને સારી બુદ્ધિની પ્રાર્થના છે. જેમ સૂર્ય સંસારને પ્રકાશ આપે છે, તેમ આપણે ઈશ્વર પાસે માંગીએ છીએ કે આપણા વિચારોને પ્રકાશ આપે જેથી આપણે સાચા નિર્ણય લઈએ. શરૂઆતના \"ૐ ભૂર્ભુવઃ સ્વઃ\" શબ્દો પરંપરામાં પાછળથી ઉમેરાયા; તે ઋગ્વેદના મૂળ મંત્રનો ભાગ નથી."], "Rigveda 1.1.1": ["ઋગ્વેદ 1.1.1", "ઋગ્વેદનો પહેલો મંત્ર", "હું અગ્નિની સ્તુતિ કરું છું, જે અગ્રણી છે, યજ્ઞના દેવ છે, ઋત્વિજ છે, દેવોને બોલાવનાર છે અને સૌથી વધુ રત્ન આપનાર છે.", "સૌથી પ્રાચીન વેદ અગ્નિથી શરૂ થાય છે. અગ્નિ મનુષ્ય અને ઈશ્વર વચ્ચેનો સેતુ છે: તેમાં જે અર્પણ કરાય, તે ઉપર પહોંચે છે. અગ્નિ ઊર્જા, પરિશ્રમ અને જ્ઞાનના પ્રકાશનું પણ પ્રતીક છે, તેથી આજે પણ દરેક શુભ પ્રસંગે દીવો કે હવન કરાય છે."], "Rigveda 1.164.46": ["ઋગ્વેદ 1.164.46", "સત્ય એક છે, જ્ઞાનીઓ તેને અનેક નામે બોલાવે છે", "તેને ઇન્દ્ર, મિત્ર, વરુણ, અગ્નિ કહે છે, અને એ જ દિવ્ય સુપર્ણ ગરુત્માન્ છે. સત્ય એક જ છે, વિદ્વાનો તેને અનેક નામે કહે છે: અગ્નિ, યમ, માતરિશ્વા.", "અનેક દેવો એક જ પરમ સત્યનાં અનેક રૂપ છે, જેમ એક જ વ્યક્તિને કોઈ \"પિતા\", કોઈ \"પુત્ર\" અને કોઈ \"ગુરુજી\" કહે છે. આ જ પંક્તિ હિન્દુ સહિષ્ણુતાનું મૂળ છે: જ્યારે સત્ય એક છે અને નામ અનેક, ત્યારે નામો પર ઝઘડવાનો કોઈ અર્થ નથી."], "Rigveda 10.90.1": ["ઋગ્વેદ 10.90.1", "પુરુષ સૂક્ત: વિરાટ પુરુષ", "વિરાટ પુરુષને હજારો મસ્તક, હજારો આંખો અને હજારો પગ છે. તેઓ પૃથ્વીને બધી બાજુથી વ્યાપીને તેનાથી પણ દસ આંગળ આગળ સ્થિત છે.", "\"સહસ્ર\"નો અર્થ છે \"અગણિત.\" બધાં પ્રાણીઓનાં મસ્તક, આંખો અને પગ એ જ એક પરમાત્માનાં અંગ છે. ઈશ્વર સંસારની અંદર પણ છે અને તેનાથી મોટા પણ. આ સૂક્ત લગભગ દરેક પૂજા અને હવનમાં બોલાય છે."], "Rigveda 7.59.12": ["ઋગ્વેદ 7.59.12", "મહામૃત્યુંજય મંત્ર", "અમે ત્રણ નેત્રોવાળા, સુગંધિત, સૌનું પોષણ કરનાર શિવની ઉપાસના કરીએ છીએ. જેમ પાકેલી કાકડી પોતાની મેળે વેલાથી છૂટી પડે છે, તેમ તેઓ અમને મૃત્યુના બંધનથી મુક્ત કરે, અમૃતથી નહીં.", "પાકી કાકડી કષ્ટ વિના વેલાથી છૂટી પડે છે. આ મંત્ર જીવનમાં એવી જ પરિપક્વતા માંગે છે: પૂરેપૂરું વિકસવું, ભય છોડવો, અને સમય આવ્યે શાંતિથી વિદાય લેવી. લોકો તેને આરોગ્ય અને સાહસ માટે જપે છે."], "Rigveda 10.191.2": ["ઋગ્વેદ 10.191.2", "સંગઠન સૂક્ત: સાથે ચાલો, સાથે બોલો", "સાથે ચાલો, સાથે બોલો, તમારાં મન એકબીજાને સમજે, જેમ પ્રાચીન દેવો એકમત થઈને પોતાનો ભાગ ગ્રહણ કરતા હતા.", "આ આખા ઋગ્વેદનું છેલ્લું સૂક્ત છે, અને તેનો વિષય છે એકતા. પરિવાર, ગામ અને દેશ ત્યારે જ આગળ વધે છે જ્યારે લોકો એક દિશામાં ચાલે, અંદરોઅંદર વાત કરે અને એકબીજાને સમજે."], "Samaveda 1 (also Rigveda 6.16.10)": ["સામવેદ 1 (ઋગ્વેદ 6.16.10 પણ)", "સામવેદનો પહેલો મંત્ર", "હે અગ્નિ! સ્તુતિ સાંભળીને અમારી આહુતિઓ ગ્રહણ કરવા આવો, અને હોતા બનીને પવિત્ર દર્ભના આસન પર બિરાજો.", "આનાથી સમજાય છે કે સામવેદ કેવી રીતે બન્યો: ઋગ્વેદનો મંત્ર લઈને તેને ગાન બનાવી દેવાયો. એ જ શબ્દો જ્યારે સૂરમાં ગવાય છે ત્યારે પ્રાર્થના એવી બની જાય છે જે સમજવા સાથે અનુભવી પણ શકાય."], "Atharvaveda 12.1.12 (part)": ["અથર્વવેદ 12.1.12 (અંશ)", "ભૂમિ સૂક્ત: પૃથ્વી મારી માતા", "ભૂમિ મારી માતા છે અને હું પૃથ્વીનો પુત્ર છું.", "ભૂમિ સૂક્તના 63 મંત્રોમાં ધરતી, તેની નદીઓ, પર્વતો, વનસ્પતિઓ અને બધા લોકો પ્રત્યે પ્રેમ છે. જો ધરતી મા છે, તો તેને નુકસાન પહોંચાડવું પાપ છે. તે વિશ્વની સૌથી પ્રાચીન પર્યાવરણ-પ્રાર્થનાઓમાંની એક છે. તેથી ઘણા લોકો સવારે પથારીમાંથી ઊતરતાં પહેલાં ધરતીને પ્રણામ કરે છે."], "Rigveda 1.89.1 (first line)": ["ઋગ્વેદ 1.89.1 (પહેલી પંક્તિ)", "બધી બાજુથી શુભ વિચારો આવે", "અમારી પાસે બધી બાજુથી કલ્યાણકારી વિચારો આવે.", "મન ખુલ્લું રાખો. સારા વિચારો ક્યાંયથી પણ અને કોઈની પાસેથી પણ આવી શકે, તેથી સૌની પાસેથી શીખવા તૈયાર રહો."], "Isha Upanishad 1 (Yajurveda 40.1)": ["ઈશોપનિષદ 1 (યજુર્વેદ 40.1)", "ઈશાવાસ્યમ્: સૌમાં ઈશ્વર", "આ સંસારમાં જે કંઈ છે, તે બધું ઈશ્વરથી વ્યાપ્ત છે. ત્યાગ ભાવથી તેનો ઉપભોગ કરો. કોઈના ધનનો લોભ ન કરો, આખરે ધન કોનું છે?", "જરૂર પૂરતો ઉપયોગ કરો અને જીવનનો આનંદ લો, પણ વળગી ન રહો, છીનવી ન લો. બધું ઈશ્વરનું છે; આપણે થોડા સમય માટે ફક્ત રખેવાળ છીએ. મહાત્મા ગાંધીએ કહ્યું હતું કે જો બધાં ઉપનિષદ નાશ પામે અને ફક્ત આ એક મંત્ર બચે, તોપણ હિન્દુ ધર્મ જીવતો રહેશે."], "Brihadaranyaka Upanishad 1.3.28": ["બૃહદારણ્યક ઉપનિષદ 1.3.28", "અસતો મા સદ્ગમય", "મને અસત્યમાંથી સત્ય તરફ લઈ જાઓ. અંધકારમાંથી પ્રકાશ તરફ લઈ જાઓ. મૃત્યુમાંથી અમરતા તરફ લઈ જાઓ.", "વિકાસનાં ત્રણ પગથિયાં: ખોટી ધારણાઓમાંથી સત્ય તરફ, અજ્ઞાનમાંથી જ્ઞાન તરફ, મૃત્યુના ભયમાંથી અમર આત્માના જ્ઞાન તરફ. આ દરેક વિદ્યાર્થી, દરેક મનુષ્યની પ્રાર્થના છે."], "Taittiriya and Katha Upanishads": ["તૈત્તિરીય અને કઠ ઉપનિષદ", "શાંતિ પાઠ: સહ નાવવતુ", "ઈશ્વર અમ બંને (ગુરુ અને શિષ્ય)ની રક્ષા કરે. અમ બંનેનું પોષણ કરે. અમે મળીને પરાક્રમ કરીએ. અમારું ભણેલું તેજસ્વી થાય. અમે ક્યારેય એકબીજાનો દ્વેષ ન કરીએ. ૐ શાંતિ, શાંતિ, શાંતિ.", "ભણતાં પહેલાં ગુરુ અને શિષ્ય સમાન રીતે એકબીજાના ભલાની પ્રાર્થના કરે છે. \"શાંતિ\" ત્રણ વાર બોલાય છે: આધ્યાત્મિક (પોતાનાં શરીર-મનથી), આધિભૌતિક (આસપાસના જગતથી) અને આધિદૈવિક (પ્રકૃતિની શક્તિઓથી) શાંતિ માટે."], "Katha Upanishad 1.3.14 (first line)": ["કઠોપનિષદ 1.3.14 (પહેલી પંક્તિ)", "ઉત્તિષ્ઠત જાગ્રત", "ઊઠો! જાગો! શ્રેષ્ઠ ગુરુઓ પાસે જઈને જ્ઞાન મેળવો.", "સ્વામી વિવેકાનંદે તેને પ્રખ્યાત કર્યું: \"ઊઠો, જાગો અને લક્ષ્ય પ્રાપ્ત ન થાય ત્યાં સુધી અટકો નહીં.\" જીવન ઊંઘમાં ન વિતાવો. જાગો, સારા ગુરુ શોધો અને શીખતા રહો."], "Gita 2.47": ["ગીતા 2.47", "કર્મણ્યેવાધિકારસ્તે", "તારો અધિકાર ફક્ત કર્મ કરવામાં છે, તેનાં ફળમાં ક્યારેય નહીં. ફળની ઇચ્છાને કર્મનું કારણ ન બનાવ, અને કર્મ છોડી દેવામાં પણ મન ન લગાવ.", "વિદ્યાર્થીએ ગુણની ચિંતામાં જકડાયા વિના પૂરા મનથી ભણવું જોઈએ. પૂરું મન મહેનતમાં લગાવો, જે તમારા હાથમાં છે. પરિણામ ઘણી બાબતો પર આધાર રાખે છે, તેથી તેનો ડર તમને રોકે નહીં. અને તેને આળસનું બહાનું પણ ન બનાવો."], "Gita 2.22": ["ગીતા 2.22", "વાસાંસિ જીર્ણાનિ", "જેમ મનુષ્ય જૂનાં વસ્ત્રો ઉતારીને નવાં વસ્ત્રો પહેરી લે છે, તેમ આત્મા જૂનું શરીર છોડીને નવું શરીર ધારણ કરે છે.", "મૃત્યુ તમારો અંત નથી. આ શ્લોક કોઈ સ્વજન ગુમાવનારને સાંત્વના આપે છે: જેને તમે પ્રેમ કર્યો, તે આત્મા નાશ પામતો નથી."], "Gita 4.7–4.8": ["ગીતા 4.7–4.8", "યદા યદા હિ ધર્મસ્ય", "હે ભારત (અર્જુન)! જ્યારે-જ્યારે ધર્મની હાનિ થાય છે અને અધર્મ વધે છે, ત્યારે-ત્યારે હું પોતે પ્રગટ થાઉં છું. સજ્જનોની રક્ષા, દુષ્ટોના વિનાશ અને ધર્મની સ્થાપના માટે હું દરેક યુગમાં અવતાર લઉં છું.", "આ જ અવતારની સંકલ્પના છે: ઈશ્વર સંસારને છોડતા નથી. જ્યારે બહુ અન્યાય થાય છે, ત્યારે તેઓ રામ, કૃષ્ણ અને અનેક રૂપે આવે છે. આ આશાનું વચન છે."], "Gita 6.5": ["ગીતા 6.5", "ઉદ્ધરેદાત્મનાત્માનમ્", "પોતાના દ્વારા પોતાનો ઉદ્ધાર કરો, પોતાને નીચે ન પાડો. મનુષ્ય પોતે જ પોતાનો મિત્ર છે અને પોતે જ પોતાનો શત્રુ.", "તમારો વિકાસ બીજું કોઈ નહીં કરી શકે. સંયમિત મન સૌથી સારો મિત્ર છે; બેલગામ મન સૌથી મોટો શત્રુ. પોતાની લગામ પોતે સંભાળો."], "Traditional prayer (Shubham Karoti)": ["પરંપરાગત પ્રાર્થના (શુભં કરોતિ)", "દીપ-પ્રાર્થના", "એ દીપ-જ્યોતને નમસ્કાર, જે શુભ, કલ્યાણ, આરોગ્ય અને ધન-સંપદા આપે છે અને શત્રુતાના ભાવનો નાશ કરે છે. દીવાની જ્યોત પરબ્રહ્મ છે, દીવાની જ્યોત જનાર્દન છે. દીવો મારાં પાપ હરી લે; દીપ-જ્યોતને નમસ્કાર.", "ઘણાં ઘરોમાં બાળકો દરરોજ સાંજે દીવો પ્રગટાવતી વખતે આ બોલે છે. દિવાળીએ પહેલી પ્રાર્થના માટે આ સૌથી યોગ્ય છે."], "Traditional mantra": ["પરંપરાગત મંત્ર", "લક્ષ્મી મંત્ર", "ૐ, શ્રીં, મહાલક્ષ્મીને નમસ્કાર.", "પૂજામાં આ 11 કે 108 વાર જપો. લક્ષ્મી દરેક પ્રકારની સમૃદ્ધિનું પ્રતીક છે: આરોગ્ય, બુદ્ધિ, દયા અને વહેંચી શકાય એટલી પૂરતી સંપત્તિ, ફક્ત ધન નહીં."], "Gita 1.1": ["ગીતા 1.1", "પહેલો પ્રશ્ન", "ધૃતરાષ્ટ્ર બોલ્યા: હે સંજય! ધર્મભૂમિ કુરુક્ષેત્રમાં યુદ્ધની ઇચ્છાથી એકઠા થયેલા મારા પુત્રો અને પાંડુના પુત્રોએ શું કર્યું?", null], "Gita 2.20": ["ગીતા 2.20", "આત્મા ન જન્મે છે, ન મરે છે", "આ આત્મા ન ક્યારેય જન્મે છે, ન ક્યારેય મરે છે. ન તે ઉત્પન્ન થઈને ફરી થનારો છે. તે અજન્મા, નિત્ય, શાશ્વત અને પુરાતન છે. શરીર મરાય ત્યારે પણ તે મરતો નથી.", "શરીર બાળપણથી યુવાની અને ઘડપણ સુધી બદલાતું રહે છે, પણ \"તમે\" એ જ રહો છો. એ જ ન બદલાતા \"તમે\" આત્મા છો. આ જાણી લેવાથી સૌથી ઊંડો ભય, મૃત્યુનો ભય, મટી જાય છે."], "Gita 2.48": ["ગીતા 2.48", "સમત્વં યોગ ઉચ્યતે", "હે ધનંજય! આસક્તિ છોડીને, યોગમાં સ્થિત થઈને કર્મ કર. સફળતા અને નિષ્ફળતામાં સમાન રહે. આ સમભાવ જ યોગ કહેવાય છે.", "યોગ ફક્ત આસનો નથી. યોગ છે સંતુલિત મન: સફળતામાં ન ઊછળવું, નિષ્ફળતામાં ન તૂટવું. શાંત મન કામ પણ વધુ સારું કરે છે."], "Gita 3.21": ["ગીતા 3.21", "શ્રેષ્ઠ જનનું આચરણ", "શ્રેષ્ઠ પુરુષ જેવું આચરણ કરે છે, બીજા લોકો પણ એવું જ કરે છે. તે જે માપદંડ સ્થાપે છે, સંસાર તેનું જ અનુસરણ કરે છે.", "બાળકો માતા-પિતાની નકલ કરે છે, ટીમ પોતાના નેતાની. જો તમે માતા-પિતા, શિક્ષક કે અધિકારી છો, તો તમારું આચરણ તમારા શબ્દો કરતાં વધુ શીખવે છે."], "Gita 3.35": ["ગીતા 3.35", "સ્વધર્મ શ્રેષ્ઠ છે", "પોતાનો ધર્મ, ભલે ગુણરહિત હોય, બીજાના સારી રીતે નિભાવાયેલા ધર્મ કરતાં શ્રેષ્ઠ છે. પોતાના ધર્મમાં મરવું પણ કલ્યાણકારી છે; બીજાનો ધર્મ ભય આપનારો છે.", "બીજાની નકલ કરીને ઉછીનું જીવન ન જીવો. પોતાના સ્વભાવ અને જવાબદારી પ્રમાણે જે ખરેખર તમારું કર્તવ્ય છે, તે જ કરો, ભલે તેમાં તમે પૂર્ણ ન હો."], "Gita 4.38": ["ગીતા 4.38", "જ્ઞાન જેવું પવિત્ર કંઈ નથી", "આ સંસારમાં જ્ઞાન જેવું પવિત્ર કરનારું કંઈ પણ નથી. યોગમાં સિદ્ધ થયેલી વ્યક્તિ સમય આવ્યે તેને પોતાની અંદર જ પામી લે છે.", "અજ્ઞાન જ સાચો મેલ છે. સાચી સમજ ભય, અપરાધ-ભાવ અને ભ્રમને ધોઈ નાખે છે, અને તે સતત અભ્યાસથી સમય સાથે વધે છે."], "Gita 5.10": ["ગીતા 5.10", "કમળના પાનની જેમ", "જે બધાં કર્મ ઈશ્વરને અર્પણ કરીને, આસક્તિ છોડીને કરે છે, તે પાપથી લેપાતો નથી, જેમ કમળનું પાન પાણીમાં રહીને પણ ભીનું થતું નથી.", "કમળ કાદવમાં ઊગીને પણ સ્વચ્છ રહે છે. તમે પરિવાર, કામ અને ધન સાથે સંસારમાં પૂરેપૂરા રહી શકો છો, લોભ અને અહંકારને તમારા પર ચોંટવા દીધા વિના."], "Gita 5.18": ["ગીતા 5.18", "પણ્ડિતાઃ સમદર્શિનઃ", "જ્ઞાનીઓ વિદ્યા અને વિનયથી સંપન્ન બ્રાહ્મણ, ગાય, હાથી, કૂતરા અને ચાંડાલમાં સમાન દૃષ્ટિ રાખે છે.", "સાચું જ્ઞાન દરેક જીવમાં, ભલે તેની જાતિ, હેસિયત કે યોનિ ગમે તે હોય, એક જ આત્મા જુએ છે. કોઈને નીચું ગણવું જ્ઞાનનું નહીં, અજ્ઞાનનું લક્ષણ છે."], "Gita 6.17": ["ગીતા 6.17", "યુક્ત આહાર-વિહાર", "જેનો આહાર-વિહાર યોગ્ય છે, કર્મોમાં પ્રયત્ન સંતુલિત છે, અને ઊંઘવું-જાગવું નિયમિત છે, તેના માટે યોગ સર્વ દુઃખોનો નાશ કરનાર બને છે.", "ન બહુ વધારે, ન બહુ ઓછું. સંતુલિત ભોજન, પૂરતી ઊંઘ, નિયમિત કામ અને થોડું મનોરંજન, કોઈ પણ આધ્યાત્મિક જીવનનો પાયો છે. અતિથી કંઈ મળતું નથી."], "Gita 6.35": ["ગીતા 6.35", "અભ્યાસ અને વૈરાગ્ય", "હે મહાબાહો! નિઃસંદેહ મન ચંચળ છે અને તેને વશમાં કરવું અઘરું છે. પરંતુ હે કુંતીપુત્ર! તે અભ્યાસ અને વૈરાગ્યથી વશમાં થાય છે.", "સ્વયં શ્રીકૃષ્ણ સ્વીકારે છે કે મનને સંભાળવું અઘરું છે, તેથી મન ભટકે તો નિરાશ ન થાઓ. તેને વારંવાર પાછું લાવો (અભ્યાસ), અને જે ભટકાવે છે તેમાંથી ધીમે-ધીમે રસ ઘટાડો (વૈરાગ્ય)."], "Gita 7.7": ["ગીતા 7.7", "દોરામાં મોતીની જેમ", "હે ધનંજય! મારાથી પર કંઈ પણ નથી. આ આખું જગત મારામાં એવી રીતે પરોવાયેલું છે જેમ દોરામાં મણિઓ.", "માળામાં મોતી દેખાય છે, દોરો નહીં, પણ દોરો જ બધાંને જોડી રાખે છે. ઈશ્વર એ જ અદૃશ્ય દોરો છે જે દરેક વ્યક્તિ અને દરેક વસ્તુને જોડે છે."], "Gita 7.16": ["ગીતા 7.16", "ચાર પ્રકારના ભક્ત", "હે અર્જુન! ચાર પ્રકારના પુણ્યાત્મા લોકો મને ભજે છે: દુઃખી (આર્ત), જ્ઞાન ઇચ્છનારા (જિજ્ઞાસુ), ધન ઇચ્છનારા (અર્થાર્થી) અને જ્ઞાની.", "કોઈ સંકટમાં પ્રાર્થના કરે છે, કોઈ જિજ્ઞાસાથી, કોઈ સફળતા માટે. શ્રીકૃષ્ણ સૌને સારા કહે છે, કારણ કે કોઈ પણ કારણે ઈશ્વર તરફ વળવું શરૂઆત છે. જે જ્ઞાની ફક્ત ઈશ્વર માટે ઈશ્વરને પ્રેમ કરે છે, તે સૌથી પ્રિય છે."], "Gita 8.5": ["ગીતા 8.5", "અંતકાળે સ્મરણ", "જે અંત સમયે મારું જ સ્મરણ કરતાં શરીર છોડીને જાય છે, તે મારા સ્વરૂપને પામે છે, તેમાં કોઈ સંદેહ નથી.", "તેથી જ પરિવારો અંતિમ સમયે વ્યક્તિ પાસે ભગવાનનું નામ લે છે. ઊંડો બોધ એ છે કે જીવનભર જે સૌથી વધુ વિચારીએ છીએ, તે જ અંતે યાદ આવે છે."], "Gita 8.7": ["ગીતા 8.7", "સ્મરણ કરો અને કર્મ કરો", "તેથી દરેક સમયે મારું સ્મરણ કર અને યુદ્ધ પણ કર. મન અને બુદ્ધિ મને અર્પણ કરીને તું નિશ્ચિત મને પામીશ.", "આધ્યાત્મિક જીવન અને સાંસારિક કર્તવ્ય અલગ નથી. કામ કરતાં, પરિવાર ચલાવતાં અને પડકારોનો સામનો કરતાં ઈશ્વરને મનમાં રાખો."], "Gita 9.22": ["ગીતા 9.22", "યોગક્ષેમં વહામ્યહમ્", "જે અનન્ય ભાવથી મારું ચિંતન કરતાં મારી ઉપાસના કરે છે, એ નિત્ય જોડાયેલા ભક્તોનો યોગક્ષેમ (જે નથી તેની પ્રાપ્તિ, જે છે તેની રક્ષા) હું પોતે વહન કરું છું.", null], "Gita 9.26": ["ગીતા 9.26", "પત્રં પુષ્પં ફલં તોયમ્", "જે મને પ્રેમથી પાન, ફૂલ, ફળ કે જળ અર્પણ કરે છે, શુદ્ધ મનવાળા એ ભક્તની પ્રેમથી આપેલી ભેટ હું સ્વીકારું છું.", "ઈશ્વરને મોંઘી ભેટ નથી જોઈતી. પ્રેમથી ચડાવેલું એક તુલસી-પત્ર દેખાડાના સોના કરતાં વધુ મૂલ્યવાન છે. સાચી ભેટ પ્રેમ છે."], "Gita 10.20": ["ગીતા 10.20", "હું સૌના હૃદયમાં આત્મા છું", "હે ગુડાકેશ (નિદ્રાને જીતનાર અર્જુન)! હું સર્વ પ્રાણીઓના હૃદયમાં સ્થિત આત્મા છું. હું જ સર્વ પ્રાણીઓનો આદિ, મધ્ય અને અંત છું.", "ઈશ્વરને શોધવા દૂર નથી જવાનું. બહારની વિભૂતિઓ ગણાવતાં પહેલાં શ્રીકૃષ્ણ કહે છે કે પહેલાં દરેક હૃદયની અંદર જુઓ."], "Gita 10.41": ["ગીતા 10.41", "દરેક શ્રેષ્ઠતા ઈશ્વરનો અંશ", "જે-જે પણ વિભૂતિયુક્ત, શોભાયુક્ત કે શક્તિયુક્ત વસ્તુ છે, તેને તું મારા તેજના અંશમાંથી ઉત્પન્ન જાણ.", "જ્યારે તમે કોઈ મહાન સંગીતકાર, સૂર્યોદય, દયાનું કામ કે શાનદાર વિચાર જુઓ છો, ત્યારે તમે ઈશ્વરની એક ઝલક જોઈ રહ્યા છો. તેનાથી સામાન્ય પ્રશંસા પણ ભક્તિ બની જાય છે."], "Gita 11.12": ["ગીતા 11.12", "હજાર સૂર્યો કરતાં પણ વધુ તેજ", "જો આકાશમાં એક સાથે હજાર સૂર્યોનો પ્રકાશ ઊગે, તો તે કદાચ એ મહાત્મા (વિશ્વરૂપ)ના તેજ સમાન થાય.", "અનંત સામે શબ્દો નાના પડે છે. 1945માં પહેલા અણુબૉમ્બના પરીક્ષણ વખતે વૈજ્ઞાનિક જે. રૉબર્ટ ઓપનહાઇમરે કહ્યું હતું કે તેમને ગીતાનો આ જ અધ્યાય યાદ આવ્યો."], "Gita 11.32": ["ગીતા 11.32", "કાલોઽસ્મિ", "હું લોકોનો નાશ કરનાર વધેલો કાળ છું, અને અહીં સૌનો સંહાર કરવામાં લાગેલો છું. તારા વિના પણ, સામેની સેનાઓમાં ઊભેલા આ બધા યોદ્ધાઓ નહીં રહે.", "જે જન્મ્યું છે, તેનો અંત નિશ્ચિત છે; કાળ સૌને લઈ જાય છે. અર્જુન સાચા કર્તા નથી. તેમને નિમિત્ત (સાધન) બનીને પોતાનું કર્તવ્ય કરવા કહેવાય છે, જ્યારે મોટી યોજના પોતાની રીતે ચાલે છે."], "Gita 12.13": ["ગીતા 12.13", "સાચા ભક્તનાં લક્ષણ", "જે કોઈ પ્રાણીનો દ્વેષ નથી કરતો, સૌનો મિત્ર અને દયાળુ છે, મમતા અને અહંકારથી રહિત છે, સુખ-દુઃખમાં સમાન છે, અને ક્ષમાશીલ છે.", "ભક્તિનું માપ એ છે કે તમે બીજાઓ સાથે કેવો વ્યવહાર કરો છો, નહીં કે કેટલો સમય પૂજા કરો છો. દ્વેષ ન કરવો, મિત્રતા, કરુણા, નમ્રતા અને ક્ષમા, આ જ સાચા ભક્તની ઓળખ છે."], "Gita 12.15": ["ગીતા 12.15", "જે ન કોઈને ઉદ્વિગ્ન કરે, ન પોતે થાય", "જેનાથી સંસારના લોકો ઉદ્વિગ્ન થતા નથી અને જે પોતે સંસારથી ઉદ્વિગ્ન થતો નથી, જે હર્ષ, ઈર્ષ્યા, ભય અને વ્યાકુળતાથી મુક્ત છે, તે મને પ્રિય છે.", "રોજની એક સરળ કસોટી: શું લોકો તમારી પાસે સહજ અનુભવે છે? અને શું બીજા અઘરા હોય ત્યારે પણ તમે શાંત રહો છો? બંનેનો અભ્યાસ કરો."], "Gita 13.2": ["ગીતા 13.2", "દરેક ક્ષેત્રમાં ક્ષેત્રજ્ઞ હું છું", "હે ભારત! સર્વ ક્ષેત્રો (શરીરો)માં ક્ષેત્રજ્ઞ પણ મને જ જાણ. ક્ષેત્ર અને ક્ષેત્રજ્ઞનું જે જ્ઞાન છે, એ જ મારા મતે સાચું જ્ઞાન છે.", "તમારી પાસે શરીર છે, પણ તમે શરીરને જાણનાર છો. \"મારી પાસે શું છે\" અને \"હું કોણ છું\" વચ્ચે ભેદ કરવો જ આધ્યાત્મિક જ્ઞાનનો સાર છે. (કેટલીક આવૃત્તિઓમાં આ શ્લોક 13.3 છે.)"], "Gita 13.27": ["ગીતા 13.27", "યઃ પશ્યતિ સ પશ્યતિ", "જે નાશ પામનારાં સર્વ પ્રાણીઓમાં સમાન રીતે સ્થિત, ક્યારેય નાશ ન પામનારા પરમેશ્વરને જુએ છે, તે જ ખરેખર જુએ છે.", "આંખો શરીરો જુએ છે, જે જન્મે છે અને મરે છે. જ્ઞાન દરેક શરીરમાં એ જ શાશ્વત હાજરી જુએ છે. આ જ સાચું જોવું છે. (કેટલીક આવૃત્તિઓમાં 13.28.)"], "Gita 14.5": ["ગીતા 14.5", "પ્રકૃતિના ત્રણ ગુણ", "હે મહાબાહો! પ્રકૃતિમાંથી ઉત્પન્ન સત્ત્વ, રજ અને તમ, આ ત્રણ ગુણો અવિનાશી આત્માને શરીરમાં બાંધે છે.", "સારપ પણ બાંધી શકે છે, સુખ અને જ્ઞાનની આસક્તિથી. પહેલાં તમસ્માંથી રજસ્ તરફ વધો (સક્રિય બનો), પછી રજસ્માંથી સત્ત્વ તરફ (શાંત અને સ્પષ્ટ બનો), અને અંતે ત્રણેયથી પર જાઓ."], "Gita 15.1": ["ગીતા 15.1", "ઊર્ધ્વમૂલ અશ્વત્થ", "કહે છે કે એક અવિનાશી અશ્વત્થ વૃક્ષ છે, જેનાં મૂળ ઉપર અને ડાળીઓ નીચે છે, અને વેદના છંદ જેનાં પાન છે. જે તેને જાણે છે, તે જ વેદનો જ્ઞાતા છે.", "સામાન્ય ઝાડ નીચેની માટીમાંથી જીવન મેળવે છે. આ સંસાર ઉપરના પરમાત્મામાંથી જીવન મેળવે છે. જો આપણે ફક્ત ડાળીઓ (વસ્તુઓ) પકડી રાખીએ, તો એ મૂળને ભૂલી જઈએ છીએ જે તેમને જીવન આપે છે."], "Gita 15.7": ["ગીતા 15.7", "મમૈવાંશો જીવલોકે", "આ જીવલોકમાં જીવાત્મા મારો જ સનાતન અંશ છે. તે પ્રકૃતિમાં સ્થિત મન સહિત છ ઇન્દ્રિયોને પોતાની તરફ ખેંચે છે.", "દરેક જીવ એ જ દિવ્ય અગ્નિનો તણખો છે. તેનાથી દરેક વ્યક્તિને ગરિમા મળે છે, અને સૌનું સન્માન કરવાનું કારણ પણ."], "Gita 16.1": ["ગીતા 16.1", "દૈવી સંપદ્ના ગુણો", "અભય, અંતઃકરણની શુદ્ધિ, જ્ઞાન અને યોગમાં દૃઢ સ્થિતિ, દાન, ઇન્દ્રિયોનો સંયમ, યજ્ઞ, સ્વાધ્યાય, તપ અને સરળતા...", "પહેલો દૈવી ગુણ અભય (નિર્ભયતા) છે. ધ્યાન આપો કે આ યાદી કર્મકાંડની નહીં, ચારિત્ર્યની છે. આ એવી યાદી છે જેનાથી કોઈ પણ પોતાનો વિકાસ કરી શકે."], "Gita 16.21": ["ગીતા 16.21", "નરકનાં ત્રણ દ્વાર", "કામ, ક્રોધ અને લોભ, આ ત્રણ નરકનાં દ્વાર છે જે આત્માનો નાશ કરે છે. તેથી આ ત્રણેયનો ત્યાગ કરવો જોઈએ.", "મનુષ્ય પોતાને અને બીજાઓને જે મોટા ભાગનું નુકસાન પહોંચાડે છે, તે આ જ ત્રણ દરવાજામાંથી આવે છે. આ નરક જોવા મૃત્યુની રાહ જોવી પડતી નથી; તે તૂટેલા પરિવારો, દેવા અને પસ્તાવામાં દેખાઈ જાય છે."], "Gita 17.3": ["ગીતા 17.3", "યો યચ્છ્રદ્ધઃ સ એવ સઃ", "હે ભારત! સૌની શ્રદ્ધા તેમના અંતઃકરણને અનુરૂપ હોય છે. મનુષ્ય શ્રદ્ધામય છે; જેની જેવી શ્રદ્ધા છે, તે એવો જ છે.", "તમે જે વસ્તુમાં ઊંડો વિશ્વાસ રાખો છો અને જેને મહત્ત્વ આપો છો, તે જ તમને ઘડે છે. સમજી-વિચારીને પસંદ કરો કે શેમાં શ્રદ્ધા રાખવી."], "Gita 17.15": ["ગીતા 17.15", "વાણીનું તપ", "જે વાણી કોઈને ઉદ્વિગ્ન ન કરે, સત્ય હોય, પ્રિય હોય અને હિતકારી હોય, અને સાથે સ્વાધ્યાયનો અભ્યાસ, આ વાણીનું તપ કહેવાય છે.", "બોલતાં પહેલાં ચાર પ્રશ્ન પૂછો: શું આ સાચું છે? શું આ મધુર છે? શું આ હિતકારી છે? શું આ કોઈને વગર કારણે દુઃખ આપશે? આ એવી સાધના છે જે આખો દિવસ થઈ શકે."], "Gita 18.66": ["ગીતા 18.66", "મામેકં શરણં વ્રજ", "બધા ધર્મો (કર્તવ્યોની ચિંતા) છોડીને ફક્ત મારે શરણે આવી જા. હું તને બધાં પાપોમાંથી મુક્ત કરી દઈશ. શોક ન કર.", null], "Gita 18.78": ["ગીતા 18.78", "યત્ર યોગેશ્વરઃ કૃષ્ણઃ", "જ્યાં યોગેશ્વર શ્રીકૃષ્ણ છે અને જ્યાં ધનુર્ધારી અર્જુન છે, ત્યાં જ શ્રી, વિજય, ઐશ્વર્ય અને અચળ નીતિ છે, એવો મારો મત છે.", "ગીતાનો છેલ્લો શ્લોક, જે સંજય કહે છે. શ્રીકૃષ્ણ દિવ્ય જ્ઞાનનું પ્રતીક છે, અર્જુન માનવ પુરુષાર્થનું. સફળતા ત્યારે મળે છે જ્યારે બંને સાથે હોય: જ્ઞાન પુરુષાર્થને માર્ગ બતાવે."], "Rigveda 10.121.1": ["ઋગ્વેદ 10.121.1", "હિરણ્યગર્ભ સૂક્ત", "સૃષ્ટિના આરંભે હિરણ્યગર્ભ પ્રગટ થયો. ઉત્પન્ન થતાં જ તે સર્વ ભૂતોનો એકમાત્ર સ્વામી હતો. તેણે પૃથ્વી અને આ આકાશને ધારણ કર્યાં. અમે કયા દેવની હવિથી ઉપાસના કરીએ?", "બ્રહ્માંડ સર્જન-શક્તિના એક ચમકતા બીજથી શરૂ થાય છે, આ જ ચિત્ર પછીથી પુરાણોમાં બ્રહ્માનું સુવર્ણ-અંડ બન્યું. દરેક મંત્રના અંતે દોહરાવાયેલા પ્રશ્ન \"કયા દેવની?\"નો જવાબ સૂક્તના છેલ્લા મંત્રમાં મળે છે: પ્રજાપતિ, સર્વ પ્રાણીઓના સ્વામી."], "Rigveda 1.164.20": ["ઋગ્વેદ 1.164.20", "એક વૃક્ષ પર બે પક્ષી", "બે સુંદર પાંખોવાળાં પક્ષી, જે સાથે રહેનારાં મિત્રો છે, એક જ વૃક્ષ પર બેઠાં છે. તેમાંથી એક સ્વાદિષ્ટ ફળ ખાય છે; બીજું ખાધા વિના ફક્ત જોતું રહે છે.", "વૃક્ષ શરીર છે. ફળ ખાનારું પક્ષી જીવાત્મા છે, જે જીવનનાં મીઠાં-કડવાં ફળ ચાખે છે. જોનારું પક્ષી પરમાત્મા છે, જે સદા શાંત છે. મુંડક અને શ્વેતાશ્વતર ઉપનિષદ આ મંત્ર દોહરાવે છે: જ્યારે પહેલું પક્ષી વળીને બીજાને જુએ છે, ત્યારે તેનો શોક મટી જાય છે."], "Rigveda 10.75.5": ["ઋગ્વેદ 10.75.5", "નદી સૂક્ત", "હે ગંગા, યમુના, સરસ્વતી, શુતુદ્રી! પરુષ્ણી સાથે મારી આ સ્તુતિ સ્વીકારો. હે મરુદ્વૃધા, અસિક્ની સાથે; હે આર્જીકીયા, વિતસ્તા અને સુષોમા સાથે, સાંભળો!", "ઉત્તર-પશ્ચિમ ભારતની નદીઓની યાદી, પૂર્વથી પશ્ચિમ તરફ. ઘણી આજે પણ ઓળખાય છે: શુતુદ્રી સતલજ છે, પરુષ્ણી રાવી, અસિક્ની ચિનાબ અને વિતસ્તા ઝેલમ. તેથી સ્નાન કરતી વખતે લોકો આ નદીઓનું આવાહન કરે છે: \"ગંગે ચ યમુને ચૈવ...\""], "Rigveda 10.117.6 (last line)": ["ઋગ્વેદ 10.117.6 (છેલ્લી પંક્તિ)", "એકલો ખાનાર", "જે એકલો ખાય છે, તે એકલો જ પાપનો ભાગીદાર થાય છે.", "આ આખું સૂક્ત (10.117) દાનની પ્રશંસા કરે છે: જે ધન વહેંચાય નહીં તે વ્યર્થ છે, અને જે ફક્ત પોતાનું પેટ ભરે તે ખરેખર જીવતો નથી. ગીતા (3.13) પણ આ જ કહે છે: જે ફક્ત પોતાના માટે રાંધે છે, તેઓ પાપ ખાય છે."], "Rigveda 10.191.4": ["ઋગ્વેદ 10.191.4", "છેલ્લો મંત્ર: એક હૃદય, એક મન", "તમારા સંકલ્પ સમાન હો, તમારાં હૃદય એક હો. તમારાં મન એક જેવાં હો, જેથી તમે સૌ મળીને સુખથી રહી શકો.", "ઋગ્વેદ, જે અગ્નિની સ્તુતિથી શરૂ થયો, લોકોની એકતાની પ્રાર્થના પર પૂરો થાય છે. ભારતમાં અનેક પરિવારો, શાળાઓ અને સંસ્થાઓ બેઠકના અંતે આ મંત્ર બોલે છે."], "Shukla Yajurveda 36.17": ["શુક્લ યજુર્વેદ 36.17", "શાંતિ પાઠ", "દ્યુલોકમાં શાંતિ હો, અંતરિક્ષમાં શાંતિ હો, પૃથ્વી પર શાંતિ હો. જળમાં, ઔષધિઓમાં, વનસ્પતિઓમાં શાંતિ હો. સર્વ દેવોમાં, બ્રહ્મમાં, બધામાં શાંતિ હો. શાંતિ પણ શાંત હો. એ શાંતિ મને પ્રાપ્ત થાઓ.", "પ્રાર્થના આકાશથી શરૂ થઈને પૃથ્વી, જળ અને વનસ્પતિઓ સુધી આવે છે, અને છેક અંતે પોતાના માટે શાંતિ માંગે છે. અંદરની શાંતિ પ્રકૃતિ અને સમાજની શાંતિ સાથે જોડાયેલી છે. તે લગભગ દરેક હિન્દુ અનુષ્ઠાનના અંતે બોલાય છે."], "Shukla Yajurveda 40.2 (Isha Upanishad 2)": ["શુક્લ યજુર્વેદ 40.2 (ઈશોપનિષદ 2)", "કર્મ કરતાં સો વર્ષ જીવો", "આ સંસારમાં કર્મ કરતાં જ સો વર્ષ જીવવાની ઇચ્છા કરો. તમારા માટે આ સિવાય બીજો કોઈ માર્ગ નથી. આ રીતે કરેલું કર્મ મનુષ્યને બાંધતું નથી.", "વેદ જીવનથી ભાગવાનું નથી કહેતા. લાંબું જીવો અને સક્રિય રહો, પણ પહેલા મંત્રની ભાવનાથી કામ કરો: બધું ઈશ્વરનું છે, લોભ વિના. આ જ ગીતાના કર્મયોગનું બીજ છે."], "Shukla Yajurveda 36.24": ["શુક્લ યજુર્વેદ 36.24", "પશ્યેમ શરદઃ શતમ્", "એ દેવોનું હિત કરનાર, ઉજ્જ્વળ નેત્ર (સૂર્ય) પૂર્વમાં ઊગી રહ્યું છે. અમે સો શરદ ઋતુઓ સુધી જોઈએ, સો વર્ષ જીવીએ, સો વર્ષ સાંભળીએ, સો વર્ષ બોલીએ, સો વર્ષ સુધી કોઈ પર આશ્રિત ન રહીએ, અને સોથી પણ વધુ.", "ઊગતા સૂર્ય પાસે લાંબા, સ્વસ્થ અને આત્મનિર્ભર જીવનની પ્રાર્થના: સારી આંખો, સારા કાન, સ્પષ્ટ વાણી, અને ઘડપણમાં પણ ગરિમા. તે ઘણી વાર જન્મદિવસે બોલાય છે."], "Shukla Yajurveda 34.1": ["શુક્લ યજુર્વેદ 34.1", "શિવસંકલ્પ સૂક્ત", "જે દિવ્ય મન જાગતી વખતે દૂર-દૂર સુધી જાય છે, અને ઊંઘમાં પણ એ જ રીતે જાય છે, જે દૂર સુધી જનારું અને જ્યોતિઓની જ્યોતિ છે, મારું એ મન શુભ સંકલ્પોવાળું હો.", null], "Shukla Yajurveda 16.1 (Rudram)": ["શુક્લ યજુર્વેદ 16.1 (રુદ્રાધ્યાય)", "નમસ્તે રુદ્ર", "હે રુદ્ર! તમારા ક્રોધને નમસ્કાર, અને તમારા બાણને નમસ્કાર. તમારી બંને ભુજાઓને પણ નમસ્કાર.", null], "Taittiriya Upanishad 1.11 (Krishna Yajurveda)": ["તૈત્તિરીય ઉપનિષદ 1.11 (કૃષ્ણ યજુર્વેદ)", "દીક્ષાંત ઉપદેશ", "સત્ય બોલો. ધર્મનું આચરણ કરો. સ્વાધ્યાયમાં આળસ ન કરો. ... માતાને દેવ માનો. પિતાને દેવ માનો. આચાર્યને દેવ માનો. અતિથિને દેવ માનો.", "આ એ ઉપદેશ છે જે વૈદિક આચાર્યો શિષ્યોને શિક્ષણ પૂરું કરીને ગૃહસ્થ જીવનમાં જતી વખતે આપતા. આજે પણ તે દીક્ષાંત સમારોહોમાં બોલાય છે, અને \"અતિથિ દેવો ભવ\" ભારતીય પર્યટનનું સૂત્ર છે."], "Chandogya Upanishad 1.1.1": ["છાંદોગ્ય ઉપનિષદ 1.1.1", "ૐની ઉપાસના", "\"ૐ\" આ અક્ષરની ઉદ્ગીથ રૂપે ઉપાસના કરવી જોઈએ, કારણ કે ઉદ્ગાતા \"ૐ\" કહીને જ ગાન શરૂ કરે છે. હવે તેની સમજૂતી છે.", "ગાયકોનું આ ઉપનિષદ એ જ ધ્વનિથી શરૂ થાય છે જેનાથી દરેક ગાન શરૂ થાય છે. ૐને આખી વાણી, આખા સંગીત અને બધા વેદોનો સાર માનવામાં આવે છે. તેથી લગભગ દરેક મંત્ર ૐથી શરૂ થાય છે."], "Chandogya Upanishad 3.14.1": ["છાંદોગ્ય ઉપનિષદ 3.14.1", "સર્વં ખલ્વિદં બ્રહ્મ", "આ બધું નિશ્ચિત બ્રહ્મ છે. બધું તેમાંથી જ જન્મે છે, તેમાં જ લીન થાય છે, અને તેમાં જ જીવે છે (તજ્જલાન્). એમ જાણીને શાંત મનથી તેની ઉપાસના કરો.", null], "Chandogya Upanishad 6.8.7": ["છાંદોગ્ય ઉપનિષદ 6.8.7", "તત્ત્વમસિ", "એ જે સૂક્ષ્મતમ સાર છે, આ આખું જગત તેને જ આત્મા રૂપે રાખે છે. એ જ સત્ય છે, એ જ આત્મા છે. હે શ્વેતકેતુ, તું તે જ છે.", "બાર વર્ષ ભણીને યુવાન શ્વેતકેતુ અભિમાન સાથે ઘરે પાછા ફર્યા. પિતા ઉદ્દાલકે તેમને વડનું બીજ તોડવા કહ્યું: \"શું દેખાય છે?\" \"કંઈ નહીં.\" \"એ જ અદૃશ્ય સારમાંથી આ વિશાળ વૃક્ષ ઊગે છે. એ જ સૂક્ષ્મ સાર સૌનો આત્મા છે, અને તું તે જ છે.\" પિતા આ ઉપદેશ નવ વાર દોહરાવે છે, પાણીમાં ઓગળેલા મીઠા જેવાં સરળ ઉદાહરણોથી."], "Chandogya Upanishad 7.23.1": ["છાંદોગ્ય ઉપનિષદ 7.23.1", "ભૂમા જ સુખ છે", "જે ભૂમા (અનંત, વિશાળ) છે, એ જ સુખ છે. અલ્પ (નાના, સીમિત)માં સુખ નથી. ભૂમા જ સુખ છે.", "નારદ બધી વિદ્યાઓ ભણીને પણ દુઃખી હતા. સનત્કુમાર તેમને કહે છે કે કોઈ પણ સીમિત વસ્તુ, ધન, યશ કે સંપત્તિ, આપણને લાંબા સમય સુધી સંતોષ આપી શકતી નથી, કારણ કે આપણને હંમેશાં વધુ જોઈએ છે. ફક્ત અનંત જ હૃદયને ભરી શકે છે."], "Kena Upanishad 1.1": ["કેન ઉપનિષદ 1.1", "કોના દ્વારા?", "કોની પ્રેરણાથી મન પોતાના વિષયો તરફ જાય છે? કોના દ્વારા પહેલો પ્રાણ ચાલે છે? કોની પ્રેરણાથી આપણે આ વાણી બોલીએ છીએ? કયા દેવ આંખ અને કાનને કામે લગાડે છે?", null], "Atharvaveda 12.1.1": ["અથર્વવેદ 12.1.1", "પૃથ્વીને કોણ ધારણ કરે છે (ભૂમિ સૂક્ત)", "મહાન સત્ય, ઉગ્ર ઋત (પ્રાકૃતિક નિયમ), દીક્ષા, તપ, બ્રહ્મ (જ્ઞાન/પ્રાર્થના) અને યજ્ઞ, આ પૃથ્વીને ધારણ કરે છે. ભૂત અને ભવિષ્યની સ્વામિની એ પૃથ્વી અમને વિશાળ સ્થાન આપે.", "આ મંત્ર કહે છે કે પૃથ્વીને કોઈ હાથી કે કાચબો નહીં, પણ મૂલ્યો ધારણ કરે છે: સત્ય, પ્રાકૃતિક નિયમ, પ્રતિબદ્ધતા અને સંયમ. જ્યારે લોકો તેમને છોડી દે છે, ત્યારે સંસાર અસ્થિર થઈ જાય છે."], "Atharvaveda 3.30.1 and 3.30.3": ["અથર્વવેદ 3.30.1 અને 3.30.3", "પરિવારમાં મેળનું સૂક્ત", "હું તમને એક હૃદયવાળા, એક મનવાળા અને દ્વેષ-રહિત બનાવું છું. એકબીજાને એવો પ્રેમ કરો જેવો ગાય પોતાના નવજાત વાછરડાને કરે છે. ભાઈ ભાઈનો દ્વેષ ન કરે, બહેન બહેનનો ન કરે. સાથે મળીને, એક સંકલ્પવાળા થઈને, અંદરોઅંદર મધુર વાણી બોલો.", "ત્રણ હજાર વર્ષ જૂનું, છતાં પરિવાર માટે સૌથી સારી સલાહ: બિનશરતી પ્રેમ, ભાઈ-બહેનોમાં દ્વેષ નહીં, સહિયારું લક્ષ્ય અને મીઠી વાણી. નવજાત વાછરડાને ચાટતી ગાયનું ચિત્ર નિઃસ્વાર્થ પ્રેમ દર્શાવે છે."], "Atharvaveda 19.15.6": ["અથર્વવેદ 19.15.6", "અભયની પ્રાર્થના", "અમને મિત્રથી અભય હો, શત્રુથી અભય હો, જાણીતાથી અભય હો, અજાણ્યાથી અભય હો. રાત્રે અભય હો, દિવસે અભય હો. બધી દિશાઓ મારી મિત્ર હો.", "જ્યારે મન ગભરાય ત્યારે બોલવા માટે એક નાની પ્રાર્થના. ભય ઘણી બાજુથી આવે છે, પરિચિત લોકોમાંથી પણ અને અણદેખી બાબતોમાંથી પણ. પ્રાર્થના એ કામના પર પૂરી થાય છે કે આખો સંસાર મિત્ર જેવો લાગે."], "Mundaka Upanishad 3.1.6": ["મુંડક ઉપનિષદ 3.1.6", "સત્યમેવ જયતે", "સત્યનો જ વિજય થાય છે, અસત્યનો નહીં. સત્યથી જ દેવોનો માર્ગ (દેવયાન) પથરાયેલો છે.", "અથર્વવેદના ઉપનિષદની આ પંક્તિ ભારતનું રાષ્ટ્રીય સૂત્ર છે, જે દરેક ચલણી નોટ અને સરકારી મહોર પર અશોક સ્તંભની નીચે લખેલી હોય છે."], "Mandukya Upanishad 1": ["માંડૂક્ય ઉપનિષદ 1", "સર્વમોઙ્કાર એવ", "ૐ, આ અક્ષર જ આ બધું છે. આ તેની સમજૂતી છે: ભૂત, વર્તમાન અને ભવિષ્ય, બધું ૐ જ છે.", "માંડૂક્ય, સૌથી નાનું મુખ્ય ઉપનિષદ, ૐના ત્રણ ધ્વનિઓથી ચેતનાની ત્રણ અવસ્થાઓ સમજાવે છે, અને ૐ પછીના મૌનથી આત્મા તરફ સંકેત કરે છે. નીચેનું ચિત્ર જુઓ."], "Isha Upanishad 9": ["ઈશોપનિષદ 9", "ફક્ત વિદ્યા કે ફક્ત અવિદ્યા નહીં", "જે ફક્ત અવિદ્યા (સાંસારિક કર્મ)ની ઉપાસના કરે છે, તેઓ ઘોર અંધકારમાં પ્રવેશે છે. અને જે ફક્ત વિદ્યા (જ્ઞાન)માં જ રમમાણ રહે છે, તેઓ જાણે તેનાથી પણ વધુ અંધકારમાં જાય છે.", "એક ચોંકાવનારો મંત્ર: આધ્યાત્મિક જ્ઞાન પણ, જો જીવન અને કર્તવ્યથી કપાઈ જાય, તો બંધન બની જાય છે. આગળના મંત્રો કહે છે કે બંને જોઈએ: સારા જીવન માટે સાંસારિક કુશળતા, અને મૃત્યુથી પર જવા માટે આધ્યાત્મિક જ્ઞાન."], "Katha Upanishad 1.2.2": ["કઠોપનિષદ 1.2.2", "શ્રેય અને પ્રેય", "શ્રેય (કલ્યાણકારી) અને પ્રેય (પ્રિય લાગતું), બંને મનુષ્ય સામે આવે છે. ધીર પુરુષ બંનેને પારખીને જુદાં પાડે છે. ધીર પ્રેયને બદલે શ્રેયને પસંદ કરે છે; મંદ બુદ્ધિવાળો લોભ અને આસક્તિથી પ્રેયને પસંદ કરે છે.", "દરરોજ આપણે પસંદ કરીએ છીએ કે અત્યારે જે સારું લાગે તે, કે જે ખરેખર આપણા માટે સારું છે તે: ફોન કે અભ્યાસ, જંક ફૂડ કે પૌષ્ટિક ભોજન, ક્રોધ કે ધીરજ. નચિકેતાએ દરેક સુખ કરતાં શ્રેયને પસંદ કર્યું, તેથી જ તે સર્વોચ્ચ જ્ઞાનનો અધિકારી બન્યો."], "Katha Upanishad 1.3.3–4": ["કઠોપનિષદ 1.3.3–4", "જીવનનો રથ", "આત્માને રથનો સ્વામી જાણો, અને શરીરને રથ. બુદ્ધિને સારથિ જાણો, અને મનને લગામ. ઇન્દ્રિયોને ઘોડા કહે છે, અને વિષયો તેમના ચાલવાના માર્ગ છે.", "આ ભારતીય ચિંતનનાં સૌથી પ્રખ્યાત ચિત્રોમાંનું એક છે. સ્પષ્ટ બુદ્ધિ જ્યારે મનને સ્થિર રાખે છે, ત્યારે ઇન્દ્રિયો સાચા માર્ગે ચાલે છે અને યાત્રા લક્ષ્ય સુધી પહોંચે છે. નીચે ચિત્ર જુઓ."], "Mundaka Upanishad 1.1.4": ["મુંડક ઉપનિષદ 1.1.4", "બે પ્રકારની વિદ્યા", "બ્રહ્મને જાણનારા કહે છે કે બે વિદ્યાઓ જાણવા યોગ્ય છે: પરા (ઉચ્ચ) અને અપરા (નિમ્ન).", "અપરા વિદ્યા એ બધું છે જે આપણે સંસાર વિશે શીખીએ છીએ: ભાષાઓ, વિજ્ઞાન, ત્યાં સુધી કે માહિતી રૂપે શાસ્ત્રો પણ. પરા વિદ્યા આત્માનો પ્રત્યક્ષ અનુભવ છે. બંનેનું મહત્ત્વ છે, પણ દુઃખનો અંત ફક્ત બીજીથી થાય છે."], "Taittiriya Upanishad 2.1": ["તૈત્તિરીય ઉપનિષદ 2.1", "સત્યં જ્ઞાનમનન્તં બ્રહ્મ", "બ્રહ્મ સત્ય છે, જ્ઞાન છે, અનંત છે.", null], "Brihadaranyaka Upanishad 2.4.5": ["બૃહદારણ્યક ઉપનિષદ 2.4.5", "આત્મનસ્તુ કામાય", "હે પ્રિયે! પતિ, પતિ માટે પ્રિય નથી હોતા; આત્મા માટે પતિ પ્રિય હોય છે.", "યાજ્ઞવલ્ક્ય આગળ કહે છે: પત્ની, પુત્ર, ધન, દેવો, આખો સંસાર, બધું આત્માને કારણે પ્રિય છે. કોઈ પ્રત્યેનો આપણો પ્રેમ ખરેખર એક જ આત્માનું બીજામાં પોતાને ઓળખવું છે. તેથી, તેઓ કહે છે, આત્માને જ જોવો, સાંભળવો, મનન કરવું અને ધ્યાન કરવું જોઈએ (શ્રવણ, મનન, નિદિધ્યાસન)."], "Brihadaranyaka Upanishad 5.2.3": ["બૃહદારણ્યક ઉપનિષદ 5.2.3", "દ દ દ: મેઘ-ગર્જનાનો ઉપદેશ", "આ જ વાત દૈવી વાણી, મેઘ-ગર્જના, દોહરાવે છે: \"દ! દ! દ!\" દમન કરો (સંયમ રાખો), દાન કરો, દયા કરો.", null], "Shvetashvatara Upanishad 2.5": ["શ્વેતાશ્વતર ઉપનિષદ 2.5", "અમૃતસ્ય પુત્રાઃ", "સાંભળો, અમૃતના સૌ પુત્રો, તમે પણ જે દિવ્ય લોકોમાં રહો છો!", "સ્વામી વિવેકાનંદે 1893માં શિકાગોની વિશ્વ ધર્મ પરિષદમાં આ મંત્ર ટાંકીને કહ્યું હતું: તમે પાપી નથી, અમૃતના પુત્રો છો. દરેક મનુષ્યમાં દિવ્ય ગરિમા છે."], "Ramayana, Bala Kanda 2.15": ["રામાયણ, બાલકાંડ 2.15", "પહેલો શ્લોક", "હે નિષાદ! તને અનંત વર્ષો સુધી પ્રતિષ્ઠા (શાંતિ) ન મળે, કારણ કે તેં પ્રેમમાં મગ્ન ક્રૌંચ પક્ષીઓની જોડીમાંથી એકને મારી નાખ્યું.", null], "Ramayana, Aranya Kanda (Maricha's words)": ["રામાયણ, અરણ્યકાંડ (મારીચનાં વચન)", "રામો વિગ્રહવાન્ ધર્મઃ", "રામ ધર્મનું સાકાર રૂપ છે.", "ધ્યાન આપવા જેવી વાત એ છે કે આ પ્રશંસા રામના શત્રુ, રાક્ષસ મારીચના મુખેથી આવે છે, જ્યારે તે રાવણને રામ સાથે ન લડવાની ચેતવણી આપે છે. શત્રુઓ પણ તેમની સારપને ઓળખતા હતા."], "Mahabharata, Vana Parva (Yaksha Prashna)": ["મહાભારત, વન પર્વ (યક્ષ-પ્રશ્ન)", "સૌથી મોટું આશ્ચર્ય", "દરરોજ પ્રાણીઓ યમલોકમાં જાય છે. છતાં જેઓ બચ્યા છે, તેઓ સદા જીવવા ઇચ્છે છે. આનાથી મોટું આશ્ચર્ય શું હોય?", "ચાર પાંડવોએ યક્ષના પ્રશ્નોના જવાબ આપ્યા વિના સરોવરનું પાણી પીધું અને મૃત થઈને પડ્યા. યુધિષ્ઠિરે દરેક પ્રશ્નનો જવાબ આપ્યો. \"સૌથી મોટું આશ્ચર્ય શું છે?\" પૂછતાં તેમણે આ જવાબ આપ્યો. પ્રસન્ન થઈને યક્ષે (સ્વયં ધર્મરાજ, તેમના પિતા) તેમના ભાઈઓને જીવતા કર્યા. આપણે સૌ જાણીએ છીએ કે મરવાનું છે, છતાં એવી રીતે જીવીએ છીએ જાણે ક્યારેય મરવાના નથી."], "Mahabharata, Anushasana Parva": ["મહાભારત, અનુશાસન પર્વ", "અહિંસા પરમો ધર્મઃ", "અહિંસા સૌથી મોટો ધર્મ છે.", "આ વાક્ય મહાભારતમાં અનેક વાર આવે છે અને તેણે મહાત્મા ગાંધીને પ્રેરણા આપી. મહાયુદ્ધનું વર્ણન કરતો આ જ ગ્રંથ શીખવે છે કે કોઈને નુકસાન ન પહોંચાડવું એ સર્વોચ્ચ મૂલ્ય છે. યુદ્ધની છૂટ ફક્ત છેલ્લા ઉપાય તરીકે હતી, જ્યારે દરેક શાંતિપૂર્ણ પ્રયાસ નિષ્ફળ જાય."], "Devi Mahatmya 5 (Markandeya Purana)": ["દેવી માહાત્મ્ય 5 (માર્કંડેય પુરાણ)", "યા દેવી સર્વભૂતેષુ", "જે દેવી સર્વ પ્રાણીઓમાં શક્તિ રૂપે રહેલાં છે, તેમને નમસ્કાર, તેમને નમસ્કાર, તેમને વારંવાર નમસ્કાર.", "દેવી માહાત્મ્યમાં આ મંત્ર વારંવાર આવે છે, દરેક વખતે નવા ગુણ સાથે: દેવી ચેતના, બુદ્ધિ, નિદ્રા, ભૂખ, ક્ષમા, શાંતિ, શ્રદ્ધા, લક્ષ્મી, દયા અને માતા રૂપે. આપણામાં દરેક સારો ગુણ જગન્માતાનું જ રૂપ છે. નવરાત્રિમાં તેનો ખાસ પાઠ થાય છે."], "Bhagavata Purana 1.3.28": ["ભાગવત પુરાણ 1.3.28", "કૃષ્ણસ્તુ ભગવાન્ સ્વયમ્", "આ બધા પરમ પુરુષના અંશ અને કળાઓ છે, પણ કૃષ્ણ તો સ્વયં ભગવાન છે. જ્યારે સંસાર દેવોના શત્રુઓથી ત્રસ્ત થાય છે, ત્યારે તેઓ યુગે-યુગે તેને સુખ આપે છે.", "અવતારોની યાદી આપ્યા પછી ભાગવત કૃષ્ણને ઈશ્વરનું પૂર્ણ રૂપ કહે છે. આ શ્લોક કૃષ્ણભક્તિની પરંપરાઓ, જેમ કે ચૈતન્ય સંપ્રદાય અને ઇસ્કૉન, ના કેન્દ્રમાં છે. (પુષ્ટિમાર્ગ અને સ્વામિનારાયણ સંપ્રદાય પણ કૃષ્ણને પરમ માને છે.)"], "Gita 1.2": ["ગીતા 1.2", "1.2 · સંજય", "સંજય બોલ્યા: પાંડવોની સેનાને વ્યૂહમાં ઊભેલી જોઈને રાજા દુર્યોધન પોતાના આચાર્ય દ્રોણ પાસે જઈને આમ બોલ્યા:", null], "Gita 1.3": ["ગીતા 1.3", "1.3 · દુર્યોધન (સંજય દ્વારા વર્ણિત)", "હે આચાર્ય! પાંડુ-પુત્રોની આ વિશાળ સેનાને જુઓ, જેને આપના જ બુદ્ધિમાન શિષ્ય, દ્રુપદ-પુત્રે વ્યૂહમાં સજાવી છે.", null], "Gita 1.4": ["ગીતા 1.4", "1.4 · દુર્યોધન (સંજય દ્વારા વર્ણિત)", "તેમાં ભીમ અને અર્જુન સમાન યુદ્ધ કરનારા મોટા-મોટા ધનુર્ધર વીરો છે: યુયુધાન, વિરાટ અને મહારથી દ્રુપદ;", null], "Gita 1.5": ["ગીતા 1.5", "1.5 · દુર્યોધન (સંજય દ્વારા વર્ણિત)", "ધૃષ્ટકેતુ, ચેકિતાન અને પરાક્રમી કાશીરાજ; પુરુજિત્, કુંતિભોજ અને નરશ્રેષ્ઠ શૈબ્ય;", null], "Gita 1.6": ["ગીતા 1.6", "1.6 · દુર્યોધન (સંજય દ્વારા વર્ણિત)", "પરાક્રમી યુધામન્યુ, વીર ઉત્તમૌજા, સુભદ્રા-પુત્ર અભિમન્યુ અને દ્રૌપદીના પુત્રો, આ બધા મહારથી છે.", null], "Gita 1.7": ["ગીતા 1.7", "1.7 · દુર્યોધન (સંજય દ્વારા વર્ણિત)", "હે દ્વિજશ્રેષ્ઠ! હવે અમારી સેનાના મુખ્ય નાયકોને પણ જાણી લો; આપની જાણકારી માટે હું તેમનાં નામ કહું છું.", null], "Gita 1.8": ["ગીતા 1.8", "1.8 · દુર્યોધન (સંજય દ્વારા વર્ણિત)", "આપ પોતે, ભીષ્મ, કર્ણ અને યુદ્ધમાં વિજયી કૃપાચાર્ય; અશ્વત્થામા, વિકર્ણ અને સોમદત્તનો પુત્ર.", null], "Gita 1.9": ["ગીતા 1.9", "1.9 · દુર્યોધન (સંજય દ્વારા વર્ણિત)", "અને બીજા પણ ઘણા વીરો છે જે મારા માટે પ્રાણ આપવા તૈયાર છે, અનેક શસ્ત્રોથી સજ્જ અને યુદ્ધમાં નિપુણ.", null], "Gita 1.10": ["ગીતા 1.10", "1.10 · દુર્યોધન (સંજય દ્વારા વર્ણિત)", "ભીષ્મ દ્વારા રક્ષિત અમારી સેના અપાર લાગે છે, જ્યારે ભીમ દ્વારા રક્ષિત તેમની સેના સીમિત છે. (કેટલાક ટીકાકારો તેનો ઊલટો અર્થ કરે છે: અમારી સેના અપૂરતી છે, તેમની પૂરતી.)", null], "Gita 1.11": ["ગીતા 1.11", "1.11 · દુર્યોધન (સંજય દ્વારા વર્ણિત)", "તેથી આપ સૌ પોતપોતાના મોરચે અડગ રહીને દરેક રીતે ભીષ્મની જ રક્ષા કરો.", null], "Gita 1.12": ["ગીતા 1.12", "1.12 · સંજય", "દુર્યોધનને પ્રસન્ન કરવા કુરુવંશના વૃદ્ધ, પ્રતાપી પિતામહ ભીષ્મે સિંહની જેમ ગર્જીને જોરથી શંખ વગાડ્યો.", null], "Gita 1.13": ["ગીતા 1.13", "1.13 · સંજય", "પછી શંખ, નગારાં, ઢોલ, મૃદંગ અને રણશિંગાં એક સાથે વાગી ઊઠ્યાં, અને ખૂબ ભયંકર નાદ થયો.", null], "Gita 1.14": ["ગીતા 1.14", "1.14 · સંજય", "ત્યારે સફેદ ઘોડાવાળા વિશાળ રથ પર બેઠેલા શ્રીકૃષ્ણ અને અર્જુને પોતાના દિવ્ય શંખ વગાડ્યા.", null], "Gita 1.15": ["ગીતા 1.15", "1.15 · સંજય", "શ્રીકૃષ્ણે પાંચજન્ય, અર્જુને દેવદત્ત, અને ભયંકર કર્મ કરનાર ભીમે પૌંડ્ર નામનો મહાશંખ વગાડ્યો.", null], "Gita 1.16": ["ગીતા 1.16", "1.16 · સંજય", "કુંતી-પુત્ર રાજા યુધિષ્ઠિરે અનંતવિજય, અને નકુલ-સહદેવે સુઘોષ અને મણિપુષ્પક નામના શંખ વગાડ્યા.", null], "Gita 1.17": ["ગીતા 1.17", "1.17 · સંજય", "શ્રેષ્ઠ ધનુર્ધર કાશીરાજ, મહારથી શિખંડી, ધૃષ્ટદ્યુમ્ન, વિરાટ અને અજેય સાત્યકિ,", null], "Gita 1.18": ["ગીતા 1.18", "1.18 · સંજય", "દ્રુપદ, દ્રૌપદીના પુત્રો અને મહાબાહુ સુભદ્રા-પુત્ર, સૌએ હે રાજન્! પોતપોતાના શંખ વગાડ્યા.", null], "Gita 1.19": ["ગીતા 1.19", "1.19 · સંજય", "આકાશ અને પૃથ્વીને ગજવતા એ ભયંકર નાદે ધૃતરાષ્ટ્રના પુત્રોનાં હૃદય હચમચાવી દીધાં.", null], "Gita 1.20": ["ગીતા 1.20", "1.20 · સંજય", "ત્યારે શસ્ત્રો ચાલવાની તૈયારીમાં જ હતાં કે હનુમાન-ધ્વજવાળા અર્જુને ધૃતરાષ્ટ્ર-પુત્રોને ઊભેલા જોઈને ધનુષ્ય ઉઠાવ્યું,", null], "Gita 1.21": ["ગીતા 1.21", "1.21 · અર્જુન", "અને શ્રીકૃષ્ણને કહ્યું: \"હે અચ્યુત! મારો રથ બંને સેનાઓની વચ્ચે ઊભો રાખો,", null], "Gita 1.22": ["ગીતા 1.22", "1.22 · અર્જુન", "જેથી હું જોઈ શકું કે યુદ્ધની ઇચ્છાથી અહીં કોણ ઊભા છે, અને આ યુદ્ધમાં મારે કોની-કોની સાથે લડવાનું છે.", null], "Gita 1.23": ["ગીતા 1.23", "1.23 · અર્જુન", "હું જોવા ઇચ્છું છું કે દુર્બુદ્ધિ દુર્યોધનનું પ્રિય કરવાની ઇચ્છાથી કોણ-કોણ યુદ્ધ કરવા આવ્યા છે.\"", null], "Gita 1.24": ["ગીતા 1.24", "1.24 · સંજય", "સંજય બોલ્યા: અર્જુને આમ કહ્યું ત્યારે શ્રીકૃષ્ણે એ ઉત્તમ રથને બંને સેનાઓની વચ્ચે લઈ જઈને ઊભો રાખ્યો,", null], "Gita 1.25": ["ગીતા 1.25", "1.25 · સંજય", "ભીષ્મ, દ્રોણ અને બધા રાજાઓની સામે, અને કહ્યું: \"હે પાર્થ! અહીં એકઠા થયેલા આ કૌરવોને જો.\"", null], "Gita 1.26": ["ગીતા 1.26", "1.26 · સંજય", "ત્યાં અર્જુને બંને સેનાઓમાં ઊભેલા પિતા સમાન વડીલો, પિતામહો, ગુરુઓ, મામાઓ, ભાઈઓ, પુત્રો, પૌત્રો અને મિત્રોને જોયા,", null], "Gita 1.27": ["ગીતા 1.27", "1.27 · સંજય", "સસરાઓ અને શુભચિંતકોને પણ. આ બધાં સગાંઓને ઊભેલાં જોઈને,", null], "Gita 1.28": ["ગીતા 1.28", "1.28 · અર્જુન", "અર્જુન ઊંડી કરુણાથી ભરાઈ ગયા અને દુઃખી થઈને બોલ્યા: \"હે કૃષ્ણ! યુદ્ધના ઇચ્છુક પોતાના જ લોકોને સામે જોઈને,", null], "Gita 1.29": ["ગીતા 1.29", "1.29 · અર્જુન", "મારાં અંગ શિથિલ થઈ રહ્યાં છે, મોં સુકાઈ રહ્યું છે, શરીર કાંપી રહ્યું છે અને રૂંવાડાં ઊભાં થઈ રહ્યાં છે.", null], "Gita 1.30": ["ગીતા 1.30", "1.30 · અર્જુન", "ગાંડીવ હાથમાંથી છૂટી રહ્યું છે, ચામડી બળી રહી છે, હું ઊભો રહી શકતો નથી, અને મારું મન ચકરાઈ રહ્યું છે.", null], "Gita 1.31": ["ગીતા 1.31", "1.31 · અર્જુન", "હે કેશવ! મને અપશુકન દેખાય છે, અને યુદ્ધમાં પોતાના જ લોકોને મારવામાં મને કોઈ ભલાઈ દેખાતી નથી.", null], "Gita 1.32": ["ગીતા 1.32", "1.32 · અર્જુન", "હે કૃષ્ણ! હું ન વિજય ઇચ્છું છું, ન રાજ્ય, ન સુખ. હે ગોવિંદ! અમારે આવા રાજ્ય, ભોગ કે જીવનથી પણ શો લાભ,", null], "Gita 1.33": ["ગીતા 1.33", "1.33 · અર્જુન", "જ્યારે એ જ લોકો, જેમના માટે અમે રાજ્ય અને સુખ ઇચ્છીએ છીએ, પ્રાણ અને ધનની આશા છોડીને યુદ્ધમાં ઊભા છે?", null], "Gita 1.34": ["ગીતા 1.34", "1.34 · અર્જુન", "ગુરુઓ, પિતાઓ, પુત્રો, પિતામહો, મામાઓ, સસરાઓ, પૌત્રો, સાળાઓ અને બીજાં સગાં.", null], "Gita 1.35": ["ગીતા 1.35", "1.35 · અર્જુન", "હે મધુસૂદન! તેઓ મને મારી પણ નાખે, તોપણ હું તેમને મારવા નથી ઇચ્છતો, ત્રણેય લોકના રાજ્ય માટે પણ નહીં, તો પછી પૃથ્વીની તો વાત જ શી.", null], "Gita 1.36": ["ગીતા 1.36", "1.36 · અર્જુન", "હે જનાર્દન! ધૃતરાષ્ટ્રના પુત્રોને મારીને અમને શું સુખ મળશે? આ આતતાયીઓને મારીને અમને પાપ જ લાગશે.", null], "Gita 1.37": ["ગીતા 1.37", "1.37 · અર્જુન", "તેથી પોતાના જ બાંધવ ધૃતરાષ્ટ્ર-પુત્રોને મારવા અમારા માટે યોગ્ય નથી. હે માધવ! પોતાના જ લોકોને મારીને અમે કેવી રીતે સુખી થઈશું?", null], "Gita 1.38": ["ગીતા 1.38", "1.38 · અર્જુન", "ભલે લોભથી આંધળા થયેલા આ લોકો કુળના નાશમાં દોષ અને મિત્રો સાથે દ્રોહમાં પાપ ન જુએ,", null], "Gita 1.39": ["ગીતા 1.39", "1.39 · અર્જુન", "પણ હે જનાર્દન! અમે, જે કુળ-નાશનો દોષ જોઈ શકીએ છીએ, આ પાપથી કેમ ન બચીએ?", null], "Gita 1.40": ["ગીતા 1.40", "1.40 · અર્જુન", "કુળના નાશથી તેની સનાતન પરંપરાઓ નાશ પામે છે; અને ધર્મ નાશ પામતાં અધર્મ આખા કુળને ઘેરી લે છે.", null], "Gita 1.41": ["ગીતા 1.41", "1.41 · અર્જુન", "હે કૃષ્ણ! અધર્મ વધતાં કુળની સ્ત્રીઓ પથભ્રષ્ટ થઈ જાય છે, અને તેનાથી વર્ણસંકર (સામાજિક વ્યવસ્થામાં ગરબડ) થાય છે.", null], "Gita 1.42": ["ગીતા 1.42", "1.42 · અર્જુન", "આ વર્ણસંકર કુળને અને કુળ-નાશકોને નરકમાં લઈ જાય છે, અને પિંડ-જળની ક્રિયા ન મળવાથી તેમના પિતૃઓ પણ પડી જાય છે.", null], "Gita 1.43": ["ગીતા 1.43", "1.43 · અર્જુન", "કુળ-નાશકોના આ દોષોથી જાતિ અને કુળના સનાતન ધર્મો નાશ પામે છે.", null], "Gita 1.44": ["ગીતા 1.44", "1.44 · અર્જુન", "હે જનાર્દન! અમે સાંભળ્યું છે કે જેમના કુળ-ધર્મ નાશ પામે છે, તેઓ લાંબા સમય સુધી નરકમાં રહે છે.", null], "Gita 1.45": ["ગીતા 1.45", "1.45 · અર્જુન", "હાય! અમે કેટલું મોટું પાપ કરવા તત્પર છીએ, કે રાજ્ય-સુખના લોભમાં પોતાના જ લોકોને મારવા તૈયાર થયા છીએ!", null], "Gita 1.46": ["ગીતા 1.46", "1.46 · અર્જુન", "મારા માટે એ જ સારું થશે કે હું શસ્ત્ર છોડીને, સામનો કર્યા વિના ઊભો રહું અને શસ્ત્રધારી ધૃતરાષ્ટ્ર-પુત્રો મને યુદ્ધમાં મારી નાખે.\"", null], "Gita 1.47": ["ગીતા 1.47", "1.47 · સંજય", "સંજય બોલ્યા: યુદ્ધભૂમિમાં આમ કહીને, શોકથી વ્યાકુળ મનવાળા અર્જુન ધનુષ્ય-બાણ છોડીને રથના પાછલા ભાગમાં બેસી ગયા.", null], "Gita 2.1": ["ગીતા 2.1", "2.1 · સંજય", "સંજય બોલ્યા: કરુણાથી ભરાયેલા, આંસુથી ભરેલી આંખોવાળા અને દુઃખી અર્જુનને શ્રીકૃષ્ણે આમ કહ્યું.", null], "Gita 2.2": ["ગીતા 2.2", "2.2 · શ્રીકૃષ્ણ", "શ્રીભગવાન બોલ્યા: હે અર્જુન! આ સંકટના સમયે આ મોહ તને ક્યાંથી આવી ગયો? તે શ્રેષ્ઠ પુરુષોને શોભતો નથી, ન સ્વર્ગ આપે છે, ન યશ.", null], "Gita 2.3": ["ગીતા 2.3", "2.3 · શ્રીકૃષ્ણ", "હે પાર્થ! કાયરતાને વશ ન થા; આ તને શોભતી નથી. હૃદયની આ તુચ્છ દુર્બળતા છોડીને ઊભો થા, હે પરંતપ!", null], "Gita 2.4": ["ગીતા 2.4", "2.4 · અર્જુન", "અર્જુન બોલ્યા: હે મધુસૂદન! હું યુદ્ધમાં ભીષ્મ અને દ્રોણ પર બાણ કેવી રીતે ચલાવું? તેઓ તો પૂજનીય છે.", null], "Gita 2.5": ["ગીતા 2.5", "2.5 · અર્જુન", "આ મહાન ગુરુઓને મારવા કરતાં સારું છે કે હું આ સંસારમાં ભીખ માંગીને જીવી લઉં. તેમને મારીને તો હું લોહીથી ખરડાયેલા ભોગ જ ભોગવીશ.", null], "Gita 2.6": ["ગીતા 2.6", "2.6 · અર્જુન", "અમે એ પણ નથી જાણતા કે શું સારું છે: અમે તેમને જીતીએ કે તેઓ અમને. સામે ધૃતરાષ્ટ્રના પુત્રો ઊભા છે, જેમને મારીને અમે જીવવા પણ નહીં ઇચ્છીએ.", null], "Gita 2.7": ["ગીતા 2.7", "2.7 · અર્જુન", "દુર્બળતા અને કરુણાએ મારા સ્વભાવને દબાવી દીધો છે, અને ધર્મના વિષયમાં મારું મન ભ્રમિત છે. મને નિશ્ચિત રીતે કહો કે મારા માટે શું શ્રેયસ્કર છે. હું આપનો શિષ્ય છું, આપને શરણે છું, મને ઉપદેશ આપો.", null], "Gita 2.8": ["ગીતા 2.8", "2.8 · અર્જુન", "પૃથ્વીનું નિષ્કંટક, સમૃદ્ધ રાજ્ય કે દેવોનું આધિપત્ય મળી જાય, તોપણ મને એવું કંઈ દેખાતું નથી જે ઇન્દ્રિયોને સૂકવી નાખતા આ શોકને દૂર કરી શકે.", null], "Gita 2.9": ["ગીતા 2.9", "2.9 · સંજય", "સંજય બોલ્યા: શ્રીકૃષ્ણને આમ કહીને અર્જુને કહ્યું, \"હે ગોવિંદ! હું યુદ્ધ નહીં કરું\", અને ચૂપ થઈ ગયા.", null], "Gita 2.10": ["ગીતા 2.10", "2.10 · સંજય", "ત્યારે બંને સેનાઓની વચ્ચે શોકમાં ડૂબેલા અર્જુનને શ્રીકૃષ્ણે જાણે સ્મિત કરતાં આ વચનો કહ્યાં.", null], "Gita 2.11": ["ગીતા 2.11", "2.11 · શ્રીકૃષ્ણ", "શ્રીભગવાન બોલ્યા: તું તેમના માટે શોક કરે છે જે શોકને યોગ્ય નથી, અને વાતો જ્ઞાનીઓ જેવી કરે છે. જ્ઞાનીઓ ન મરેલાઓ માટે શોક કરે છે, ન જીવતાઓ માટે.", null], "Gita 2.12": ["ગીતા 2.12", "2.12 · શ્રીકૃષ્ણ", "એવો કોઈ સમય ન હતો જ્યારે હું ન હતો, કે તું ન હતો, કે આ રાજાઓ ન હતા; અને ન આગળ ક્યારેય એવું થશે કે આપણે ન રહીએ.", null], "Gita 2.13": ["ગીતા 2.13", "2.13 · શ્રીકૃષ્ણ", "જેમ આ શરીરમાં આત્મા બાળપણ, યુવાની અને ઘડપણમાંથી પસાર થાય છે, તેમ જ બીજું શરીર પામે છે. ધીર પુરુષ તેનાથી મોહિત થતો નથી.", null], "Gita 2.14": ["ગીતા 2.14", "2.14 · શ્રીકૃષ્ણ", "ઇન્દ્રિયો અને વિષયોના મેળથી ઠંડી-ગરમી, સુખ-દુઃખ થાય છે. તે આવતાં-જતાં રહે છે અને કાયમી નથી. હે ભારત! તેમને સહન કરતાં શીખ.", null], "Gita 2.15": ["ગીતા 2.15", "2.15 · શ્રીકૃષ્ણ", "જે વ્યક્તિ તેમનાથી વિચલિત નથી થતી, સુખ-દુઃખમાં સમાન અને ધીર રહે છે, તે અમૃતત્વને યોગ્ય થાય છે.", null], "Gita 2.16": ["ગીતા 2.16", "2.16 · શ્રીકૃષ્ણ", "અસત્નું અસ્તિત્વ નથી, અને સત્નો ક્યારેય અભાવ થતો નથી. તત્ત્વદર્શીઓએ બંનેનો સાર જાણી લીધો છે.", null], "Gita 2.17": ["ગીતા 2.17", "2.17 · શ્રીકૃષ્ણ", "જેનાથી આ બધું વ્યાપ્ત છે, તેને અવિનાશી જાણ. એ અવિનાશીનો નાશ કોઈ કરી શકતું નથી.", null], "Gita 2.18": ["ગીતા 2.18", "2.18 · શ્રીકૃષ્ણ", "આ શરીરો નશ્વર કહેવાયાં છે, પણ તેમાં રહેનારો આત્મા નિત્ય, અવિનાશી અને અપ્રમેય છે. તેથી હે ભારત! યુદ્ધ કર.", null], "Gita 2.19": ["ગીતા 2.19", "2.19 · શ્રીકૃષ્ણ", "જે આત્માને મારનાર માને છે અને જે તેને મરેલો માને છે, બંને નથી જાણતા. આ ન મારે છે, ન મરાય છે.", null], "Gita 2.21": ["ગીતા 2.21", "2.21 · શ્રીકૃષ્ણ", "હે પાર્થ! જે આત્માને અવિનાશી, નિત્ય, અજન્મા અને અવ્યય જાણે છે, તે કોઈને કેવી રીતે મારે કે મરાવે?", null], "Gita 2.23": ["ગીતા 2.23", "2.23 · શ્રીકૃષ્ણ", "તેને શસ્ત્રો કાપી શકતાં નથી, અગ્નિ બાળી શકતો નથી, જળ ભીંજવી શકતું નથી, અને વાયુ સૂકવી શકતો નથી.", null], "Gita 2.24": ["ગીતા 2.24", "2.24 · શ્રીકૃષ્ણ", "તે ન કપાય છે, ન બળે છે, ન ભીંજાય છે, ન સુકાય છે. તે નિત્ય, સર્વવ્યાપી, સ્થિર, અચળ અને સનાતન છે.", null], "Gita 2.25": ["ગીતા 2.25", "2.25 · શ્રીકૃષ્ણ", "તે અવ્યક્ત, અચિંત્ય અને અવિકારી કહેવાય છે. તેને આવો જાણીને તારે શોક ન કરવો જોઈએ.", null], "Gita 2.26": ["ગીતા 2.26", "2.26 · શ્રીકૃષ્ણ", "અને જો તું તેને વારંવાર જન્મનારો અને મરનારો માને, તોપણ હે મહાબાહો! તારે શોક ન કરવો જોઈએ.", null], "Gita 2.27": ["ગીતા 2.27", "2.27 · શ્રીકૃષ્ણ", "કારણ કે જે જન્મ્યો છે તેનું મૃત્યુ નિશ્ચિત છે, અને જે મર્યો છે તેનો જન્મ નિશ્ચિત છે. તેથી જે ટાળી ન શકાય, તેના માટે શોક ન કર.", null], "Gita 2.28": ["ગીતા 2.28", "2.28 · શ્રીકૃષ્ણ", "હે ભારત! પ્રાણીઓ જન્મ પહેલાં અપ્રગટ હતાં, વચ્ચે પ્રગટ છે, અને મૃત્યુ પછી ફરી અપ્રગટ થઈ જાય છે. તેમાં શોકની શી વાત છે?", null], "Gita 2.29": ["ગીતા 2.29", "2.29 · શ્રીકૃષ્ણ", "કોઈ તેને આશ્ચર્યની જેમ જુએ છે, કોઈ આશ્ચર્યની જેમ તેનું વર્ણન કરે છે, કોઈ આશ્ચર્યની જેમ સાંભળે છે; અને સાંભળીને પણ કોઈ તેને બરાબર જાણતું નથી.", null], "Gita 2.30": ["ગીતા 2.30", "2.30 · શ્રીકૃષ્ણ", "હે ભારત! સૌના શરીરમાં રહેનારો આ આત્મા સદા અવધ્ય છે. તેથી તારે કોઈ પણ પ્રાણી માટે શોક ન કરવો જોઈએ.", null], "Gita 2.31": ["ગીતા 2.31", "2.31 · શ્રીકૃષ્ણ", "પોતાના ધર્મને જોઈને પણ તારે ડગમગવું ન જોઈએ; ક્ષત્રિય માટે ધર્મયુદ્ધથી વધીને કંઈ નથી.", null], "Gita 2.32": ["ગીતા 2.32", "2.32 · શ્રીકૃષ્ણ", "હે પાર્થ! તે ક્ષત્રિયો ભાગ્યશાળી છે જેમને પોતાની મેળે આવેલું, સ્વર્ગના ખુલ્લા દ્વાર જેવું આવું ધર્મયુદ્ધ મળે છે.", null], "Gita 2.33": ["ગીતા 2.33", "2.33 · શ્રીકૃષ્ણ", "પણ જો તું આ ધર્મયુદ્ધ નહીં કરે, તો પોતાનો ધર્મ અને યશ ખોઈને પાપનો ભાગીદાર બનીશ.", null], "Gita 2.34": ["ગીતા 2.34", "2.34 · શ્રીકૃષ્ણ", "લોકો સદા તારી અપકીર્તિની ચર્ચા કરશે, અને સન્માનિત વ્યક્તિ માટે અપકીર્તિ મૃત્યુથી પણ ખરાબ છે.", null], "Gita 2.35": ["ગીતા 2.35", "2.35 · શ્રીકૃષ્ણ", "મહારથીઓ સમજશે કે તું ડરીને યુદ્ધમાંથી ભાગ્યો, અને જેઓ તારું બહુ સન્માન કરતા હતા, તેમની નજરમાં તું નાનો થઈ જઈશ.", null], "Gita 2.36": ["ગીતા 2.36", "2.36 · શ્રીકૃષ્ણ", "તારા શત્રુઓ તારી શક્તિની નિંદા કરતાં ઘણી ન કહેવા જેવી વાતો કહેશે. તેનાથી વધુ દુઃખની વાત શી હોય?", null], "Gita 2.37": ["ગીતા 2.37", "2.37 · શ્રીકૃષ્ણ", "મરાયો તો સ્વર્ગ પામીશ; જીત્યો તો પૃથ્વીનું રાજ્ય ભોગવીશ. તેથી હે કૌંતેય! યુદ્ધનો નિશ્ચય કરીને ઊભો થા.", null], "Gita 2.38": ["ગીતા 2.38", "2.38 · શ્રીકૃષ્ણ", "સુખ-દુઃખ, લાભ-હાનિ અને જય-પરાજયને સમાન ગણીને યુદ્ધ માટે તૈયાર થા. આમ કરવાથી તને પાપ નહીં લાગે.", null], "Gita 2.39": ["ગીતા 2.39", "2.39 · શ્રીકૃષ્ણ", "આ જ્ઞાન મેં તને સાંખ્યની દૃષ્ટિએ કહ્યું. હવે તેને યોગની દૃષ્ટિએ સાંભળ; આ બુદ્ધિથી યુક્ત થઈને તું કર્મનું બંધન તોડી નાખીશ.", null], "Gita 2.40": ["ગીતા 2.40", "2.40 · શ્રીકૃષ્ણ", "આ માર્ગમાં કરેલો પ્રયાસ ક્યારેય વ્યર્થ જતો નથી અને ઊલટું ફળ થતું નથી. આ ધર્મનું થોડું પાલન પણ મોટા ભયથી બચાવે છે.", null], "Gita 2.41": ["ગીતા 2.41", "2.41 · શ્રીકૃષ્ણ", "હે કુરુનંદન! આ માર્ગમાં નિશ્ચયાત્મક બુદ્ધિ એક જ હોય છે; અનિશ્ચયી લોકોની બુદ્ધિ અનેક શાખાઓમાં વિખરાયેલી અને અનંત હોય છે.", null], "Gita 2.42": ["ગીતા 2.42", "2.42 · શ્રીકૃષ્ણ", "જે અવિવેકી લોકો વેદના શબ્દોમાં જ રમમાણ રહે છે અને કહે છે \"આ સિવાય કંઈ નથી\",", null], "Gita 2.43": ["ગીતા 2.43", "2.43 · શ્રીકૃષ્ણ", "જે કામનાઓથી ભરેલા અને સ્વર્ગને જ લક્ષ્ય માનનારા છે, તેઓ ભોગ અને ઐશ્વર્ય આપનારા કર્મકાંડોની લોભામણી વાતો કરે છે, જેનું ફળ પુનર્જન્મ છે.", null], "Gita 2.44": ["ગીતા 2.44", "2.44 · શ્રીકૃષ્ણ", "જે ભોગ અને ઐશ્વર્યમાં આસક્ત છે અને આવી વાતોથી જેમનું મન ભટકી ગયું છે, તેમની બુદ્ધિ ધ્યાનમાં સ્થિર થઈ શકતી નથી.", null], "Gita 2.45": ["ગીતા 2.45", "2.45 · શ્રીકૃષ્ણ", "વેદો ત્રણ ગુણોના વિષયોનું વર્ણન કરે છે. હે અર્જુન! તું ત્રણેય ગુણોથી ઉપર ઊઠ: દ્વંદ્વોથી મુક્ત, સદા સત્ત્વમાં સ્થિત, મેળવવા અને સાચવવાની ચિંતાથી રહિત, અને આત્મામાં સ્થિત.", null], "Gita 2.46": ["ગીતા 2.46", "2.46 · શ્રીકૃષ્ણ", "જ્યારે ચારે બાજુ પાણી ભરેલું હોય, ત્યારે નાના કૂવાનો જેટલો ઉપયોગ છે, સત્યને જાણનાર જ્ઞાની માટે બધા વેદોનો એટલો જ ઉપયોગ છે.", null], "Gita 2.49": ["ગીતા 2.49", "2.49 · શ્રીકૃષ્ણ", "હે ધનંજય! ફળની ઇચ્છાથી કરેલું કર્મ આ સમબુદ્ધિવાળા કર્મ કરતાં ઘણું નિમ્ન છે. આ બુદ્ધિનું શરણ લે. ફળ માટે જ કર્મ કરનારા દયાને પાત્ર છે.", null], "Gita 2.50": ["ગીતા 2.50", "2.50 · શ્રીકૃષ્ણ", "સમબુદ્ધિવાળી વ્યક્તિ અહીં જ સારાં-ખરાબ બંને ફળોથી મુક્ત થઈ જાય છે. તેથી યોગમાં લાગી જા: કર્મમાં કુશળતા જ યોગ છે.", null], "Gita 2.51": ["ગીતા 2.51", "2.51 · શ્રીકૃષ્ણ", "સમબુદ્ધિવાળા જ્ઞાનીઓ કર્મના ફળને ત્યાગીને જન્મના બંધનમાંથી મુક્ત થઈ જાય છે અને દુઃખથી પર પદને પામે છે.", null], "Gita 2.52": ["ગીતા 2.52", "2.52 · શ્રીકૃષ્ણ", "જ્યારે તારી બુદ્ધિ મોહના કાદવને પાર કરી લેશે, ત્યારે તું સાંભળેલી અને સાંભળવાની બાબતોથી ઉદાસીન થઈ જઈશ.", null], "Gita 2.53": ["ગીતા 2.53", "2.53 · શ્રીકૃષ્ણ", "અનેક વાતો સાંભળીને વિચલિત થયેલી તારી બુદ્ધિ જ્યારે ધ્યાનમાં અચળ અને સ્થિર થઈ જશે, ત્યારે તું યોગને પામીશ.", null], "Gita 2.54": ["ગીતા 2.54", "2.54 · અર્જુન", "અર્જુન બોલ્યા: હે કેશવ! સ્થિર બુદ્ધિવાળી, સમાધિમાં સ્થિત વ્યક્તિનાં શાં લક્ષણ છે? તે કેવી રીતે બોલે છે, કેવી રીતે બેસે છે, કેવી રીતે ચાલે છે?", null], "Gita 2.55": ["ગીતા 2.55", "2.55 · શ્રીકૃષ્ણ", "શ્રીભગવાન બોલ્યા: હે પાર્થ! જ્યારે વ્યક્તિ મનની બધી કામનાઓ ત્યાગી દે છે અને આત્માથી આત્મામાં જ સંતુષ્ટ રહે છે, ત્યારે તે સ્થિતપ્રજ્ઞ કહેવાય છે.", null], "Gita 2.56": ["ગીતા 2.56", "2.56 · શ્રીકૃષ્ણ", "જેનું મન દુઃખમાં વિચલિત થતું નથી, જેને સુખની લાલસા નથી, અને જે રાગ, ભય અને ક્રોધથી મુક્ત છે, તે સ્થિર બુદ્ધિવાળો મુનિ કહેવાય છે.", null], "Gita 2.57": ["ગીતા 2.57", "2.57 · શ્રીકૃષ્ણ", "જે કોઈમાં આસક્ત નથી, જે સારું મળતાં ન પ્રસન્ન થાય છે અને ખરાબ મળતાં ન દ્વેષ કરે છે, તેની બુદ્ધિ સ્થિર છે.", null], "Gita 2.58": ["ગીતા 2.58", "2.58 · શ્રીકૃષ્ણ", "જેમ કાચબો પોતાનાં અંગો સમેટી લે છે, તેમ જે ઇન્દ્રિયોને વિષયોમાંથી પૂરેપૂરી હટાવી લે છે, તેની બુદ્ધિ સ્થિર છે.", null], "Gita 2.59": ["ગીતા 2.59", "2.59 · શ્રીકૃષ્ણ", "વિષયોનું સેવન ન કરવાથી વિષયો તો છૂટી જાય છે, પણ તેમનો રસ (લાલસા) રહી જાય છે. પરમાત્માનું દર્શન થતાં એ રસ પણ છૂટી જાય છે.", null], "Gita 2.60": ["ગીતા 2.60", "2.60 · શ્રીકૃષ્ણ", "હે કૌંતેય! ચંચળ ઇન્દ્રિયો પ્રયત્ન કરનારા બુદ્ધિમાન વ્યક્તિના મનને પણ બળપૂર્વક હરી લે છે.", null], "Gita 2.61": ["ગીતા 2.61", "2.61 · શ્રીકૃષ્ણ", "બધી ઇન્દ્રિયોને વશમાં કરીને, મારામાં મન લગાવીને યોગમાં બેસવું જોઈએ. જેની ઇન્દ્રિયો વશમાં છે, તેની બુદ્ધિ સ્થિર છે.", null], "Gita 2.62": ["ગીતા 2.62", "2.62 · શ્રીકૃષ્ણ", "વિષયોનું ચિંતન કરવાથી તેમાં આસક્તિ થાય છે; આસક્તિમાંથી કામના થાય છે, અને કામનામાંથી ક્રોધ ઉત્પન્ન થાય છે.", null], "Gita 2.63": ["ગીતા 2.63", "2.63 · શ્રીકૃષ્ણ", "ક્રોધમાંથી મોહ થાય છે; મોહમાંથી સ્મૃતિ ભ્રમિત થાય છે; સ્મૃતિના ભ્રમથી બુદ્ધિનો નાશ થાય છે; અને બુદ્ધિના નાશથી વ્યક્તિનું પતન થઈ જાય છે.", null], "Gita 2.64": ["ગીતા 2.64", "2.64 · શ્રીકૃષ્ણ", "પણ જે આત્મ-સંયમી વ્યક્તિ રાગ-દ્વેષથી મુક્ત, વશમાં રાખેલી ઇન્દ્રિયોથી વિષયો વચ્ચે રહે છે, તે પ્રસન્નતા (શાંતિ) પામે છે.", null], "Gita 2.65": ["ગીતા 2.65", "2.65 · શ્રીકૃષ્ણ", "એ પ્રસન્નતામાં બધાં દુઃખ મટી જાય છે, અને પ્રસન્ન ચિત્તવાળાની બુદ્ધિ જલદી જ સ્થિર થઈ જાય છે.", null], "Gita 2.66": ["ગીતા 2.66", "2.66 · શ્રીકૃષ્ણ", "જે સંયમી નથી, તેનામાં ન વિવેક હોય છે, ન ભાવના (ધ્યાન). ધ્યાન વિના શાંતિ નથી, અને શાંતિ વિના સુખ કેવી રીતે?", null], "Gita 2.67": ["ગીતા 2.67", "2.67 · શ્રીકૃષ્ણ", "જ્યારે મન ભટકતી ઇન્દ્રિયોની પાછળ ચાલે છે, ત્યારે તે બુદ્ધિને એવી રીતે હરી લે છે જેમ પવન પાણીમાં હોડીને તાણી જાય છે.", null], "Gita 2.68": ["ગીતા 2.68", "2.68 · શ્રીકૃષ્ણ", "તેથી હે મહાબાહો! જેની ઇન્દ્રિયો વિષયોમાંથી પૂરેપૂરી રોકાયેલી છે, તેની બુદ્ધિ સ્થિર છે.", null], "Gita 2.69": ["ગીતા 2.69", "2.69 · શ્રીકૃષ્ણ", "જે સર્વ પ્રાણીઓ માટે રાત છે, તેમાં સંયમી જાગે છે; અને જેમાં સર્વ પ્રાણીઓ જાગે છે, તે જ્ઞાની મુનિ માટે રાત છે.", null], "Gita 2.70": ["ગીતા 2.70", "2.70 · શ્રીકૃષ્ણ", "જેમ નદીઓ ભરેલા, અચળ સમુદ્રમાં સમાઈ જાય છે અને તે વિચલિત થતો નથી, તેમ જેનામાં બધી કામનાઓ વિકાર વિના સમાઈ જાય છે, તે શાંતિ પામે છે, કામનાઓ પાછળ દોડનાર નહીં.", null], "Gita 2.71": ["ગીતા 2.71", "2.71 · શ્રીકૃષ્ણ", "જે બધી કામનાઓ છોડીને, લાલસા, મમતા અને અહંકારથી રહિત થઈને જીવે છે, તે શાંતિ પામે છે.", null], "Gita 2.72": ["ગીતા 2.72", "2.72 · શ્રીકૃષ્ણ", "હે પાર્થ! આ બ્રાહ્મી સ્થિતિ છે. તેને પામીને વ્યક્તિ ફરી મોહિત થતી નથી. અંતકાળે પણ તેમાં સ્થિત થઈને તે બ્રહ્મનિર્વાણ (બ્રહ્મની શાંતિ)ને પામે છે.", null], "Gita 3.1": ["ગીતા 3.1", "3.1 · અર્જુન", "અર્જુન બોલ્યા: હે જનાર્દન! જો આપ જ્ઞાનને કર્મ કરતાં શ્રેષ્ઠ માનો છો, તો હે કેશવ! મને આ ભયંકર કર્મમાં કેમ જોડો છો?", null], "Gita 3.2": ["ગીતા 3.2", "3.2 · અર્જુન", "આપનાં ભેળસેળવાળાં વચનોથી મારી બુદ્ધિ ભ્રમિત થઈ રહી છે. મને નિશ્ચિત રીતે એ એક માર્ગ કહો જેનાથી મારું કલ્યાણ થાય.", null], "Gita 3.3": ["ગીતા 3.3", "3.3 · શ્રીકૃષ્ણ", "શ્રીભગવાન બોલ્યા: હે નિષ્પાપ! જેમ મેં પહેલાં કહ્યું, આ સંસારમાં બે માર્ગ છે: ચિંતનશીલો માટે જ્ઞાનયોગ, અને કર્મશીલો માટે કર્મયોગ.", null], "Gita 3.4": ["ગીતા 3.4", "3.4 · શ્રીકૃષ્ણ", "કર્મ શરૂ ન કરવા માત્રથી કોઈ કર્મ-બંધનમાંથી મુક્ત થતું નથી, અને ફક્ત ત્યાગથી સિદ્ધિ મળતી નથી.", null], "Gita 3.5": ["ગીતા 3.5", "3.5 · શ્રીકૃષ્ણ", "કોઈ પણ ક્ષણભર પણ કર્મ કર્યા વિના રહી શકતું નથી; પ્રકૃતિના ગુણો સૌને વિવશ કરીને કર્મ કરાવે છે.", null], "Gita 3.6": ["ગીતા 3.6", "3.6 · શ્રીકૃષ્ણ", "જે કર્મેન્દ્રિયોને રોકીને મનથી વિષયોનું ચિંતન કરતો રહે છે, તે મૂઢ છે અને મિથ્યાચારી (પાખંડી) કહેવાય છે.", null], "Gita 3.7": ["ગીતા 3.7", "3.7 · શ્રીકૃષ્ણ", "પણ હે અર્જુન! જે મનથી ઇન્દ્રિયોને વશમાં કરીને, આસક્તિ વિના કર્મેન્દ્રિયોથી કર્મયોગ કરે છે, તે શ્રેષ્ઠ છે.", null], "Gita 3.8": ["ગીતા 3.8", "3.8 · શ્રીકૃષ્ણ", "તું તારું નિયત કર્મ કર, કારણ કે કર્મ ન કરવા કરતાં કર્મ કરવું શ્રેષ્ઠ છે. કર્મ વિના તો શરીરનો નિર્વાહ પણ થઈ શકતો નથી.", null], "Gita 3.9": ["ગીતા 3.9", "3.9 · શ્રીકૃષ્ણ", "યજ્ઞ (અર્પણ) માટે કરેલાં કર્મ સિવાયનાં બીજાં કર્મ મનુષ્યને બાંધે છે. તેથી હે કૌંતેય! આસક્તિ છોડીને એ જ ભાવથી કર્મ કર.", null], "Gita 3.10": ["ગીતા 3.10", "3.10 · શ્રીકૃષ્ણ", "શરૂઆતમાં પ્રજાપતિએ યજ્ઞ સાથે પ્રજાને રચીને કહ્યું: \"આનાથી તમે ફૂલો-ફાલો; આ તમારી ઇચ્છાઓ પૂરી કરનારી કામધેનુ હો.\"", null], "Gita 3.11": ["ગીતા 3.11", "3.11 · શ્રીકૃષ્ણ", "આનાથી તમે દેવોને સંતુષ્ટ કરો, અને દેવો તમને સંતુષ્ટ કરે. એકબીજાનું ધ્યાન રાખતાં તમે પરમ કલ્યાણ પામશો.", null], "Gita 3.12": ["ગીતા 3.12", "3.12 · શ્રીકૃષ્ણ", "યજ્ઞથી પ્રસન્ન દેવો તમને ઇચ્છિત ભોગ આપશે. જે તેમણે આપેલી વસ્તુઓનો ભોગ કંઈ પાછું આપ્યા વિના કરે છે, તે ચોર જ છે.", null], "Gita 3.13": ["ગીતા 3.13", "3.13 · શ્રીકૃષ્ણ", "યજ્ઞમાંથી બચેલું ખાનારા સજ્જનો બધાં પાપોમાંથી મુક્ત થઈ જાય છે; પણ જે ફક્ત પોતાના માટે રાંધે છે, તેઓ પાપ જ ખાય છે.", null], "Gita 3.14": ["ગીતા 3.14", "3.14 · શ્રીકૃષ્ણ", "પ્રાણીઓ અન્નમાંથી ઉત્પન્ન થાય છે, અન્ન વરસાદથી, વરસાદ યજ્ઞથી, અને યજ્ઞ કર્મમાંથી ઉત્પન્ન થાય છે.", null], "Gita 3.15": ["ગીતા 3.15", "3.15 · શ્રીકૃષ્ણ", "કર્મને વેદમાંથી ઉત્પન્ન જાણ, અને વેદને અવિનાશી (પરમાત્મા)માંથી. તેથી સર્વવ્યાપી બ્રહ્મ સદા યજ્ઞમાં સ્થિત છે.", null], "Gita 3.16": ["ગીતા 3.16", "3.16 · શ્રીકૃષ્ણ", "હે પાર્થ! જે આ રીતે ચલાવેલા ચક્રનું પાલન નથી કરતો અને ઇન્દ્રિયોમાં રમીને પાપમય જીવન જીવે છે, તે વ્યર્થ જ જીવે છે.", null], "Gita 3.17": ["ગીતા 3.17", "3.17 · શ્રીકૃષ્ણ", "પણ જે આત્મામાં જ રમે છે, આત્મામાં જ તૃપ્ત અને સંતુષ્ટ છે, તેના માટે કોઈ કર્તવ્ય બાકી રહેતું નથી.", null], "Gita 3.18": ["ગીતા 3.18", "3.18 · શ્રીકૃષ્ણ", "આવી વ્યક્તિને ન કર્મ કરવાથી કોઈ પ્રયોજન છે, ન ન કરવાથી; અને તે કોઈ પ્રાણી પર કોઈ બાબત માટે આધાર રાખતી નથી.", null], "Gita 3.19": ["ગીતા 3.19", "3.19 · શ્રીકૃષ્ણ", "તેથી આસક્તિ છોડીને સદા કરવા યોગ્ય કર્મ કરતો રહે. આસક્તિ વિના કર્મ કરવાથી મનુષ્ય પરમાત્માને પામે છે.", null], "Gita 3.20": ["ગીતા 3.20", "3.20 · શ્રીકૃષ્ણ", "જનક વગેરેએ કર્મથી જ સિદ્ધિ મેળવી. લોક-કલ્યાણ (લોકસંગ્રહ)ને જોતાં પણ તારે કર્મ કરવું જોઈએ.", null], "Gita 3.22": ["ગીતા 3.22", "3.22 · શ્રીકૃષ્ણ", "હે પાર્થ! ત્રણેય લોકમાં મારા માટે કંઈ પણ કરવાનું બાકી નથી, ન કંઈ મેળવવાનું બાકી છે; છતાં હું કર્મમાં લાગેલો રહું છું.", null], "Gita 3.23": ["ગીતા 3.23", "3.23 · શ્રીકૃષ્ણ", "કારણ કે જો હું સાવધાનીથી કર્મ ન કરું, તો લોકો દરેક રીતે મારા જ માર્ગે ચાલશે.", null], "Gita 3.24": ["ગીતા 3.24", "3.24 · શ્રીકૃષ્ણ", "જો હું કર્મ ન કરું, તો આ લોકો નાશ પામે; હું અવ્યવસ્થાનું કારણ બનું અને આ પ્રજાઓનો નાશ કરું.", null], "Gita 3.25": ["ગીતા 3.25", "3.25 · શ્રીકૃષ્ણ", "હે ભારત! જેમ અજ્ઞાનીઓ આસક્ત થઈને કર્મ કરે છે, તેમ જ જ્ઞાનીએ લોક-કલ્યાણની ઇચ્છાથી, આસક્તિ વિના કર્મ કરવું જોઈએ.", null], "Gita 3.26": ["ગીતા 3.26", "3.26 · શ્રીકૃષ્ણ", "જ્ઞાનીએ કર્મમાં આસક્ત અજ્ઞાનીઓની બુદ્ધિમાં ભ્રમ ન નાખવો જોઈએ; પણ પોતે યોગથી કર્મ કરતાં તેમને પણ કર્મમાં જોડવા જોઈએ.", null], "Gita 3.27": ["ગીતા 3.27", "3.27 · શ્રીકૃષ્ણ", "બધાં કર્મ પ્રકૃતિના ગુણો દ્વારા થાય છે, પણ અહંકારથી મોહિત વ્યક્તિ વિચારે છે, \"હું કર્તા છું.\"", null], "Gita 3.28": ["ગીતા 3.28", "3.28 · શ્રીકૃષ્ણ", "પણ હે મહાબાહો! જે ગુણો અને કર્મોના વિભાગનું તત્ત્વ જાણે છે, તે સમજે છે કે \"ગુણો જ ગુણોમાં વર્તે છે\" અને આસક્ત થતો નથી.", null], "Gita 3.29": ["ગીતા 3.29", "3.29 · શ્રીકૃષ્ણ", "પ્રકૃતિના ગુણોથી મોહિત લોકો ગુણોનાં કર્મોમાં આસક્ત રહે છે. પૂર્ણ જ્ઞાનીએ અધૂરી સમજવાળા મંદબુદ્ધિ લોકોને વિચલિત ન કરવા જોઈએ.", null], "Gita 3.30": ["ગીતા 3.30", "3.30 · શ્રીકૃષ્ણ", "બધાં કર્મ મને અર્પણ કરીને, મનને આત્મામાં લગાવીને, કામના અને મમતાથી રહિત થઈને, શોક-રૂપી તાવ છોડીને યુદ્ધ કર.", null], "Gita 3.31": ["ગીતા 3.31", "3.31 · શ્રીકૃષ્ણ", "જે લોકો શ્રદ્ધા સાથે, દોષ કાઢ્યા વિના, સદા મારા આ મતનું પાલન કરે છે, તેઓ પણ કર્મોમાંથી મુક્ત થઈ જાય છે.", null], "Gita 3.32": ["ગીતા 3.32", "3.32 · શ્રીકૃષ્ણ", "પણ જે મારા આ મતમાં દોષ કાઢીને તેનું પાલન નથી કરતા, તેમને બધા જ્ઞાનમાં મોહિત, વિવેકહીન અને નાશ પામેલા જાણ.", null], "Gita 3.33": ["ગીતા 3.33", "3.33 · શ્રીકૃષ્ણ", "જ્ઞાની પણ પોતાના સ્વભાવ પ્રમાણે જ ચેષ્ટા કરે છે. બધાં પ્રાણીઓ પોતાની પ્રકૃતિ પ્રમાણે ચાલે છે; હઠથી દબાવવાથી શું થશે?", null], "Gita 3.34": ["ગીતા 3.34", "3.34 · શ્રીકૃષ્ણ", "ઇન્દ્રિયોના વિષયોમાં રાગ અને દ્વેષ સ્વાભાવિક રીતે રહે છે; પણ તેમને વશ ન થા, કારણ કે તેઓ કલ્યાણના માર્ગના શત્રુ છે.", null], "Gita 3.36": ["ગીતા 3.36", "3.36 · અર્જુન", "અર્જુન બોલ્યા: હે વાર્ષ્ણેય! તો પછી મનુષ્ય ન ઇચ્છતાં પણ, જાણે બળપૂર્વક પ્રેરાઈને, પાપ કેમ કરે છે?", null], "Gita 3.37": ["ગીતા 3.37", "3.37 · શ્રીકૃષ્ણ", "શ્રીભગવાન બોલ્યા: આ કામ છે, આ જ ક્રોધ છે, જે રજોગુણમાંથી ઉત્પન્ન થાય છે. તે ક્યારેય તૃપ્ત થતો નથી અને મહાપાપી છે. તેને જ અહીં શત્રુ જાણ.", null], "Gita 3.38": ["ગીતા 3.38", "3.38 · શ્રીકૃષ્ણ", "જેમ ધુમાડાથી અગ્નિ, ધૂળથી દર્પણ અને ઓરથી ગર્ભ ઢંકાયેલો રહે છે, તેમ કામનાથી જ્ઞાન ઢંકાયેલું રહે છે.", null], "Gita 3.39": ["ગીતા 3.39", "3.39 · શ્રીકૃષ્ણ", "હે કૌંતેય! જ્ઞાનીઓના આ નિત્ય શત્રુ, કામના-રૂપી ક્યારેય તૃપ્ત ન થનારા અગ્નિથી જ્ઞાન ઢંકાયેલું રહે છે.", null], "Gita 3.40": ["ગીતા 3.40", "3.40 · શ્રીકૃષ્ણ", "ઇન્દ્રિયો, મન અને બુદ્ધિ તેનું નિવાસ-સ્થાન કહેવાય છે. તેમના દ્વારા તે જ્ઞાનને ઢાંકીને જીવાત્માને મોહિત કરે છે.", null], "Gita 3.41": ["ગીતા 3.41", "3.41 · શ્રીકૃષ્ણ", "તેથી હે ભરતશ્રેષ્ઠ! પહેલાં ઇન્દ્રિયોને વશમાં કર, પછી જ્ઞાન અને વિજ્ઞાનનો નાશ કરનાર આ પાપીને મારી નાખ.", null], "Gita 3.42": ["ગીતા 3.42", "3.42 · શ્રીકૃષ્ણ", "ઇન્દ્રિયો (શરીરથી) શ્રેષ્ઠ કહેવાય છે; ઇન્દ્રિયોથી શ્રેષ્ઠ મન છે; મનથી શ્રેષ્ઠ બુદ્ધિ છે; અને બુદ્ધિથી પણ શ્રેષ્ઠ તે (આત્મા) છે.", null], "Gita 3.43": ["ગીતા 3.43", "3.43 · શ્રીકૃષ્ણ", "આ રીતે આત્માને બુદ્ધિથી શ્રેષ્ઠ જાણીને, આત્મા દ્વારા મનને સ્થિર કરીને, હે મહાબાહો! આ મુશ્કેલીથી જીતાય તેવા કામના-રૂપી શત્રુને જીત.", null], "Gita 4.1": ["ગીતા 4.1", "4.1 · શ્રીકૃષ્ણ", "શ્રીકૃષ્ણ બોલ્યા: આ અવિનાશી યોગ મેં સૂર્યદેવ વિવસ્વાનને શીખવ્યો. વિવસ્વાને તે મનુને કહ્યો, અને મનુએ રાજા ઇક્ષ્વાકુને.", null], "Gita 4.2": ["ગીતા 4.2", "4.2 · શ્રીકૃષ્ણ", "આ રીતે ગુરુ-શિષ્ય પરંપરાથી મળેલો આ યોગ રાજર્ષિઓએ જાણ્યો. પણ હે અર્જુન, ઘણો સમય વીતતાં આ યોગ સંસારમાંથી લુપ્ત થઈ ગયો.", null], "Gita 4.3": ["ગીતા 4.3", "4.3 · શ્રીકૃષ્ણ", "આજે મેં તને એ જ જૂનો યોગ કહ્યો છે, કારણ કે તું મારો ભક્ત અને મિત્ર છે. આ સૌથી ઉત્તમ રહસ્ય છે.", null], "Gita 4.4": ["ગીતા 4.4", "4.4 · અર્જુન", "અર્જુન બોલ્યા: આપનો જન્મ તો હમણાં થયો છે અને વિવસ્વાનનો જન્મ ઘણો પહેલાં થયો હતો. હું કેવી રીતે સમજું કે આપે શરૂઆતમાં તેમને આ શીખવ્યો?", null], "Gita 4.5": ["ગીતા 4.5", "4.5 · શ્રીકૃષ્ણ", "શ્રીકૃષ્ણ બોલ્યા: હે અર્જુન, મારા અને તારા ઘણા જન્મો વીતી ગયા છે. હું તે બધા જાણું છું, તું નથી જાણતો.", null], "Gita 4.6": ["ગીતા 4.6", "4.6 · શ્રીકૃષ્ણ", "હું અજન્મા અને અવિનાશી છું, સર્વ પ્રાણીઓનો ઈશ્વર છું, છતાં પોતાની પ્રકૃતિને વશમાં રાખીને પોતાની માયાથી પ્રગટ થાઉં છું.", null], "Gita 4.9": ["ગીતા 4.9", "4.9 · શ્રીકૃષ્ણ", "જે મારા જન્મ અને કર્મના દિવ્ય સ્વરૂપને સાચે જ જાણી લે છે, તે શરીર છોડ્યા પછી ફરી જન્મ લેતો નથી. હે અર્જુન, તે મને પામે છે.", null], "Gita 4.10": ["ગીતા 4.10", "4.10 · શ્રીકૃષ્ણ", "રાગ, ભય અને ક્રોધથી મુક્ત, મારામાં લીન અને મારે શરણે આવેલા, ઘણા લોકો જ્ઞાન રૂપી તપથી પવિત્ર થઈને મારા ભાવને પામ્યા છે.", null], "Gita 4.11": ["ગીતા 4.11", "4.11 · શ્રીકૃષ્ણ", "જે જે ભાવથી મારે શરણે આવે છે, હું તેમને એ જ રીતે અપનાવું છું. હે પાર્થ, બધા મનુષ્યો દરેક રીતે મારા જ માર્ગે ચાલે છે.", null], "Gita 4.12": ["ગીતા 4.12", "4.12 · શ્રીકૃષ્ણ", "જે કર્મોનું જલદી ફળ ઇચ્છે છે, તેઓ અહીં દેવોની પૂજા કરે છે, કારણ કે મનુષ્ય-લોકમાં કર્મથી મળતી સફળતા જલદી મળે છે.", null], "Gita 4.13": ["ગીતા 4.13", "4.13 · શ્રીકૃષ્ણ", "ગુણ અને કર્મના વિભાગ પ્રમાણે ચાર વર્ણ મેં રચ્યા. તેમનો કર્તા હોવા છતાં મને અકર્તા અને અવિનાશી જાણ.", null], "Gita 4.14": ["ગીતા 4.14", "4.14 · શ્રીકૃષ્ણ", "કર્મો મને લેપતાં નથી, અને મને કર્મફળની ઇચ્છા નથી. જે મને આ રીતે જાણે છે, તે પણ કર્મોથી બંધાતો નથી.", null], "Gita 4.15": ["ગીતા 4.15", "4.15 · શ્રીકૃષ્ણ", "આ જાણીને પ્રાચીન મોક્ષ ઇચ્છનારાઓએ પણ કર્મ કર્યાં. તેથી તું પણ કર્મ કર, જેમ પૂર્વજોએ ઘણા સમય પહેલાં કર્યાં હતાં.", null], "Gita 4.16": ["ગીતા 4.16", "4.16 · શ્રીકૃષ્ણ", "કર્મ શું છે અને અકર્મ શું છે, એ વિષયમાં જ્ઞાનીઓ પણ મૂંઝાઈ જાય છે. હું તને કર્મનું રહસ્ય કહીશ, જેને જાણીને તું અશુભમાંથી મુક્ત થઈ જઈશ.", null], "Gita 4.17": ["ગીતા 4.17", "4.17 · શ્રીકૃષ્ણ", "કર્મને સમજવું જોઈએ, વિકર્મ (ખોટા કર્મ)ને પણ સમજવું જોઈએ અને અકર્મને પણ. કર્મની ગતિ ઘણી ઊંડી છે.", null], "Gita 4.18": ["ગીતા 4.18", "4.18 · શ્રીકૃષ્ણ", "જે કર્મમાં અકર્મ જુએ છે અને અકર્મમાં કર્મ, તે જ મનુષ્યોમાં બુદ્ધિમાન છે. તે બધાં કર્મ કરતાં પણ યોગમાં સ્થિત છે.", null], "Gita 4.19": ["ગીતા 4.19", "4.19 · શ્રીકૃષ્ણ", "જેનાં બધાં કાર્યો કામના અને સ્વાર્થી સંકલ્પથી રહિત છે, અને જેનાં કર્મો જ્ઞાનના અગ્નિમાં બળી ગયાં છે, તેને જ્ઞાનીઓ પંડિત કહે છે.", null], "Gita 4.20": ["ગીતા 4.20", "4.20 · શ્રીકૃષ્ણ", "કર્મફળની આસક્તિ છોડીને, સદા તૃપ્ત અને કોઈ પર આધાર ન રાખનારો, કર્મમાં પૂરેપૂરો લાગેલો રહીને પણ કંઈ કરતો નથી.", null], "Gita 4.21": ["ગીતા 4.21", "4.21 · શ્રીકૃષ્ણ", "આશાથી રહિત, મન અને ઇન્દ્રિયોને વશમાં રાખનારો, બધા સંગ્રહનો ત્યાગ કરનારો, ફક્ત શરીર માટે કર્મ કરતાં કોઈ પાપ પામતો નથી.", null], "Gita 4.22": ["ગીતા 4.22", "4.22 · શ્રીકૃષ્ણ", "જે પોતાની મેળે મળે તેમાં સંતુષ્ટ, સુખ-દુઃખ જેવાં દ્વંદ્વોથી પર, ઈર્ષ્યાથી રહિત, સફળતા અને નિષ્ફળતામાં સમાન રહે છે, તે કર્મ કરીને પણ બંધાતો નથી.", null], "Gita 4.23": ["ગીતા 4.23", "4.23 · શ્રીકૃષ્ણ", "જે આસક્તિથી રહિત અને મુક્ત છે, જેનું ચિત્ત જ્ઞાનમાં સ્થિત છે, અને જે યજ્ઞ-ભાવથી કર્મ કરે છે, તેનાં બધાં કર્મ પૂરેપૂરાં વિલીન થઈ જાય છે.", null], "Gita 4.24": ["ગીતા 4.24", "4.24 · શ્રીકૃષ્ણ", "અર્પણ બ્રહ્મ છે, હવિ બ્રહ્મ છે, બ્રહ્મ રૂપી અગ્નિમાં બ્રહ્મ દ્વારા આહુતિ અપાય છે. જે દરેક કર્મમાં બ્રહ્મને જુએ છે, તે બ્રહ્મને જ પામે છે.", null], "Gita 4.25": ["ગીતા 4.25", "4.25 · શ્રીકૃષ્ણ", "કેટલાક યોગીઓ દેવો માટે યજ્ઞ કરે છે. બીજા બ્રહ્મ રૂપી અગ્નિમાં યજ્ઞ દ્વારા જ યજ્ઞની આહુતિ આપે છે.", null], "Gita 4.26": ["ગીતા 4.26", "4.26 · શ્રીકૃષ્ણ", "કેટલાક લોકો શ્રવણ વગેરે ઇન્દ્રિયોને સંયમ રૂપી અગ્નિમાં અર્પણ કરે છે. બીજા શબ્દ વગેરે વિષયોને ઇન્દ્રિય રૂપી અગ્નિમાં અર્પણ કરે છે.", null], "Gita 4.27": ["ગીતા 4.27", "4.27 · શ્રીકૃષ્ણ", "બીજા લોકો ઇન્દ્રિયો અને પ્રાણોનાં બધાં કર્મોને જ્ઞાનથી પ્રગટાવેલા આત્મ-સંયમ રૂપી યોગ-અગ્નિમાં અર્પણ કરે છે.", null], "Gita 4.28": ["ગીતા 4.28", "4.28 · શ્રીકૃષ્ણ", "કેટલાક લોકો ધનનો યજ્ઞ કરે છે, કેટલાક તપનો, કેટલાક યોગનો, અને દૃઢ વ્રતવાળા કેટલાક સાધકો સ્વાધ્યાય અને જ્ઞાનનો યજ્ઞ કરે છે.", null], "Gita 4.29": ["ગીતા 4.29", "4.29 · શ્રીકૃષ્ણ", "બીજા પ્રાણાયામમાં લાગેલા સાધકો પ્રાણને અપાનમાં અને અપાનને પ્રાણમાં અર્પણ કરે છે, બંનેની ગતિ રોકીને.", null], "Gita 4.30": ["ગીતા 4.30", "4.30 · શ્રીકૃષ્ણ", "બીજા લોકો નિયમિત આહાર કરતાં પ્રાણોને પ્રાણોમાં અર્પણ કરે છે. આ બધા યજ્ઞને જાણનારા છે, અને યજ્ઞથી તેમના દોષ મટી જાય છે.", null], "Gita 4.31": ["ગીતા 4.31", "4.31 · શ્રીકૃષ્ણ", "યજ્ઞમાંથી બચેલા અમૃત રૂપી અન્નને ખાનારા સનાતન બ્રહ્મને પામે છે. જે યજ્ઞ નથી કરતો, તેના માટે આ લોક પણ નથી, તો પરલોક ક્યાંથી?", null], "Gita 4.32": ["ગીતા 4.32", "4.32 · શ્રીકૃષ્ણ", "વેદોમાં આ રીતે અનેક પ્રકારના યજ્ઞો કહેવાયા છે. જાણ કે તે બધા કર્મમાંથી ઉત્પન્ન થાય છે. આ જાણીને તું મુક્ત થઈ જઈશ.", null], "Gita 4.33": ["ગીતા 4.33", "4.33 · શ્રીકૃષ્ણ", "હે પરંતપ, દ્રવ્યથી થતા યજ્ઞ કરતાં જ્ઞાન-યજ્ઞ શ્રેષ્ઠ છે. હે પાર્થ, બધાં કર્મ પૂરેપૂરાં જ્ઞાનમાં જ સમાપ્ત થાય છે.", null], "Gita 4.34": ["ગીતા 4.34", "4.34 · શ્રીકૃષ્ણ", "એ જ્ઞાનને નમ્ર પ્રણામથી, સાચા પ્રશ્નો પૂછીને અને સેવા કરીને જાણ. સત્યને જોઈ ચૂકેલા જ્ઞાનીઓ તને એ જ્ઞાન શીખવશે.", null], "Gita 4.35": ["ગીતા 4.35", "4.35 · શ્રીકૃષ્ણ", "હે પાંડવ, તેને જાણીને તું ફરી ક્યારેય આવા મોહમાં નહીં પડે. તેનાથી તું સર્વ પ્રાણીઓને પોતાનામાં અને પછી મારામાં જોઈશ.", null], "Gita 4.36": ["ગીતા 4.36", "4.36 · શ્રીકૃષ્ણ", "જો તું બધા પાપીઓમાં સૌથી મોટો પાપી પણ હોય, તોપણ જ્ઞાન રૂપી હોડીથી બધાં પાપોને પાર કરી જઈશ.", null], "Gita 4.37": ["ગીતા 4.37", "4.37 · શ્રીકૃષ્ણ", "હે અર્જુન, જેમ સળગતો અગ્નિ લાકડાંને રાખ કરી નાખે છે, તેમ જ્ઞાનનો અગ્નિ બધાં કર્મોને રાખ કરી નાખે છે.", null], "Gita 4.39": ["ગીતા 4.39", "4.39 · શ્રીકૃષ્ણ", "શ્રદ્ધાવાન, તેમાં લાગેલી અને ઇન્દ્રિયોને વશમાં રાખનારી વ્યક્તિ જ્ઞાન પામે છે. જ્ઞાન પામીને તે જલદી જ પરમ શાંતિ પ્રાપ્ત કરે છે.", null], "Gita 4.40": ["ગીતા 4.40", "4.40 · શ્રીકૃષ્ણ", "અજ્ઞાની, શ્રદ્ધાહીન અને સંશયથી ભરેલી વ્યક્તિ નાશ પામે છે. સંશય કરનાર માટે ન આ લોક છે, ન પરલોક, ન સુખ.", null], "Gita 4.41": ["ગીતા 4.41", "4.41 · શ્રીકૃષ્ણ", "હે ધનંજય, જેણે યોગથી કર્મોનો ત્યાગ કર્યો છે, જ્ઞાનથી જેના સંશય કપાઈ ગયા છે અને જે આત્મામાં સ્થિત છે, તેને કર્મો બાંધતાં નથી.", null], "Gita 4.42": ["ગીતા 4.42", "4.42 · શ્રીકૃષ્ણ", "તેથી અજ્ઞાનમાંથી જન્મેલા, હૃદયમાં બેઠેલા આ સંશયને જ્ઞાનની તલવારથી કાપી નાખ. યોગનો આશરો લે. હે ભારત, ઊભો થા!", null], "Gita 5.1": ["ગીતા 5.1", "5.1 · અર્જુન", "અર્જુન બોલ્યા: હે કૃષ્ણ, આપ કર્મોના સંન્યાસની પ્રશંસા કરો છો અને પછી કર્મયોગની પણ. આ બંનેમાં જે નિશ્ચિત રીતે શ્રેષ્ઠ હોય, તે મને કહો.", null], "Gita 5.2": ["ગીતા 5.2", "5.2 · શ્રીકૃષ્ણ", "શ્રીકૃષ્ણ બોલ્યા: કર્મ-સંન્યાસ અને કર્મયોગ બંને પરમ કલ્યાણ તરફ લઈ જાય છે. પણ એ બંનેમાં કર્મ-સંન્યાસ કરતાં કર્મયોગ શ્રેષ્ઠ છે.", null], "Gita 5.3": ["ગીતા 5.3", "5.3 · શ્રીકૃષ્ણ", "જે ન દ્વેષ કરે છે, ન કામના કરે છે, તેને સદાનો સંન્યાસી જાણ. હે મહાબાહો, દ્વંદ્વોથી મુક્ત તે સહેલાઈથી બંધનમાંથી છૂટી જાય છે.", null], "Gita 5.4": ["ગીતા 5.4", "5.4 · શ્રીકૃષ્ણ", "જ્ઞાન-માર્ગ (સાંખ્ય) અને કર્મ-માર્ગ (યોગ)ને અલગ-અલગ અણસમજુ લોકો કહે છે, જ્ઞાનીઓ નહીં. આમાંથી કોઈ એક પર પણ બરાબર ચાલનાર બંનેનું ફળ પામે છે.", null], "Gita 5.5": ["ગીતા 5.5", "5.5 · શ્રીકૃષ્ણ", "જે સ્થાન જ્ઞાન-માર્ગથી મળે છે, તે જ કર્મ-માર્ગથી પણ મળે છે. જે સાંખ્ય અને યોગને એક જુએ છે, તે જ ખરેખર જુએ છે.", null], "Gita 5.6": ["ગીતા 5.6", "5.6 · શ્રીકૃષ્ણ", "પણ હે મહાબાહો, કર્મયોગ વિના સંન્યાસ પામવો અઘરો છે. યોગમાં લાગેલો મુનિ જલદી જ બ્રહ્મને પામે છે.", null], "Gita 5.7": ["ગીતા 5.7", "5.7 · શ્રીકૃષ્ણ", "યોગમાં સ્થિત, શુદ્ધ હૃદયવાળો, મન અને ઇન્દ્રિયોને જીતી ચૂકેલો, સર્વ પ્રાણીઓમાં પોતાનો જ આત્મા જોનારો, કર્મ કરતાં પણ લેપાતો નથી.", null], "Gita 5.8": ["ગીતા 5.8", "5.8 · શ્રીકૃષ્ણ", "તત્ત્વને જાણનારો યોગી જોતાં, સાંભળતાં, સ્પર્શતાં, સૂંઘતાં, ખાતાં, ચાલતાં, ઊંઘતાં અને શ્વાસ લેતાં પણ એમ જ માને છે કે \"હું કંઈ જ કરતો નથી\",", null], "Gita 5.9": ["ગીતા 5.9", "5.9 · શ્રીકૃષ્ણ", "બોલતાં, છોડતાં, પકડતાં, આંખો ખોલતાં અને બંધ કરતાં પણ, એમ સમજતાં કે ફક્ત ઇન્દ્રિયો પોતાના વિષયોમાં વર્તે છે.", null], "Gita 5.11": ["ગીતા 5.11", "5.11 · શ્રીકૃષ્ણ", "યોગીઓ આસક્તિ છોડીને, પોતાની શુદ્ધિ માટે, શરીર, મન, બુદ્ધિ અને ફક્ત ઇન્દ્રિયોથી કર્મ કરે છે.", null], "Gita 5.12": ["ગીતા 5.12", "5.12 · શ્રીકૃષ્ણ", "યોગમાં સ્થિત વ્યક્તિ કર્મફળ છોડીને કાયમી શાંતિ પામે છે. અસ્થિર વ્યક્તિ કામનાથી પ્રેરાઈને અને ફળમાં આસક્ત થઈને બંધાઈ જાય છે.", null], "Gita 5.13": ["ગીતા 5.13", "5.13 · શ્રીકૃષ્ણ", "મનથી બધાં કર્મોનો ત્યાગ કરીને, સંયમી આત્મા નવ દ્વારવાળા નગર, એટલે કે શરીર,માં સુખથી રહે છે, ન કર્મ કરે છે, ન કરાવે છે.", null], "Gita 5.14": ["ગીતા 5.14", "5.14 · શ્રીકૃષ્ણ", "પ્રભુ લોકોનું કર્તાપણું, કર્મ કે કર્મ અને ફળનો સંબંધ રચતા નથી. આ બધું સ્વભાવ (પ્રકૃતિ) જ કરે છે.", null], "Gita 5.15": ["ગીતા 5.15", "5.15 · શ્રીકૃષ્ણ", "સર્વવ્યાપી પ્રભુ કોઈનું પાપ કે પુણ્ય લેતા નથી. જ્ઞાન અજ્ઞાનથી ઢંકાયેલું છે, તેનાથી જ પ્રાણીઓ મોહિત થાય છે.", null], "Gita 5.16": ["ગીતા 5.16", "5.16 · શ્રીકૃષ્ણ", "પણ જેમનું અજ્ઞાન આત્મ-જ્ઞાનથી નાશ પામ્યું છે, તેમનું જ્ઞાન સૂર્યની જેમ ચમકીને પરમ તત્ત્વને પ્રગટ કરી દે છે.", null], "Gita 5.17": ["ગીતા 5.17", "5.17 · શ્રીકૃષ્ણ", "જેમની બુદ્ધિ તેમાં, આત્મા તેમાં, નિષ્ઠા તેમાં અને લક્ષ્ય એ જ છે, જ્ઞાનથી જેમના દોષ ધોવાઈ ગયા છે, તેઓ એ અવસ્થા પામે છે જ્યાંથી પાછા ફરવાનું નથી.", null], "Gita 5.19": ["ગીતા 5.19", "5.19 · શ્રીકૃષ્ણ", "જેમનું મન સમતામાં સ્થિત છે, તેમણે અહીં જ સંસારને જીતી લીધો. બ્રહ્મ નિર્દોષ અને સૌમાં સમાન છે, તેથી તેઓ બ્રહ્મમાં સ્થિત છે.", null], "Gita 5.20": ["ગીતા 5.20", "5.20 · શ્રીકૃષ્ણ", "પ્રિય મળતાં બહુ હરખાય નહીં, અપ્રિય મળતાં વિચલિત ન થાય. સ્થિર બુદ્ધિવાળો, મોહથી રહિત બ્રહ્મજ્ઞાની બ્રહ્મમાં સ્થિત રહે છે.", null], "Gita 5.21": ["ગીતા 5.21", "5.21 · શ્રીકૃષ્ણ", "બહારનાં સુખોમાં આસક્ત ન થઈને વ્યક્તિ અંદર સુખ પામે છે. યોગથી બ્રહ્મ સાથે જોડાયેલી તે ક્યારેય ન મટનારું સુખ ભોગવે છે.", null], "Gita 5.22": ["ગીતા 5.22", "5.22 · શ્રીકૃષ્ણ", "ઇન્દ્રિયોના સંપર્કથી ઉત્પન્ન ભોગો દુઃખનાં જ કારણ છે. હે કૌંતેય, તેમનો આદિ અને અંત છે; બુદ્ધિમાન તેમાં રમતો નથી.", null], "Gita 5.23": ["ગીતા 5.23", "5.23 · શ્રીકૃષ્ણ", "જે શરીર છૂટતાં પહેલાં અહીં જ કામ અને ક્રોધના વેગને સહી શકે છે, તે જ યોગી છે અને તે જ સુખી મનુષ્ય છે.", null], "Gita 5.24": ["ગીતા 5.24", "5.24 · શ્રીકૃષ્ણ", "જેનું સુખ અંદર છે, જેનો આનંદ અંદર છે અને જેનો પ્રકાશ અંદર છે, તે યોગી બ્રહ્મ-રૂપ થઈને બ્રહ્મ-નિર્વાણ (પરમ શાંતિ) પામે છે.", null], "Gita 5.25": ["ગીતા 5.25", "5.25 · શ્રીકૃષ્ણ", "જેમના દોષ મટી ગયા છે, સંશય કપાઈ ગયા છે, જે સંયમી છે અને સર્વ પ્રાણીઓના હિતમાં લાગેલા રહે છે, તે ઋષિઓ બ્રહ્મ-નિર્વાણ પામે છે.", null], "Gita 5.26": ["ગીતા 5.26", "5.26 · શ્રીકૃષ્ણ", "જે કામ અને ક્રોધથી મુક્ત છે, જેમણે મનને વશમાં કર્યું છે અને આત્માને જાણી લીધો છે, તેમના માટે બ્રહ્મ-નિર્વાણ ચારે બાજુ નજીક જ છે.", null], "Gita 5.27": ["ગીતા 5.27", "5.27 · શ્રીકૃષ્ણ", "બહારના વિષયોને બહાર જ છોડીને, દૃષ્ટિને ભ્રમરોની વચ્ચે ટકાવીને, નાસિકામાં ચાલતા પ્રાણ અને અપાનને સમ કરીને,", null], "Gita 5.28": ["ગીતા 5.28", "5.28 · શ્રીકૃષ્ણ", "ઇન્દ્રિય, મન અને બુદ્ધિને વશમાં રાખીને, મોક્ષને લક્ષ્ય બનાવનાર, ઇચ્છા, ભય અને ક્રોધથી રહિત મુનિ સદા મુક્ત જ છે.", null], "Gita 5.29": ["ગીતા 5.29", "5.29 · શ્રીકૃષ્ણ", "મને સર્વ યજ્ઞો અને તપોનો ભોક્તા, સર્વ લોકોનો મહાન ઈશ્વર અને સર્વ પ્રાણીઓનો સુહૃદ (મિત્ર) જાણીને વ્યક્તિ શાંતિ પામે છે.", null], "Gita 6.1": ["ગીતા 6.1", "6.1 · શ્રીકૃષ્ણ", "શ્રીકૃષ્ણ બોલ્યા: જે કર્મફળનો આશરો લીધા વિના કરવા યોગ્ય કર્મ કરે છે, તે જ સંન્યાસી અને યોગી છે; ફક્ત અગ્નિ કે કર્મ છોડી દેનારો નહીં.", null], "Gita 6.2": ["ગીતા 6.2", "6.2 · શ્રીકૃષ્ણ", "હે પાંડવ, જેને સંન્યાસ કહે છે, તેને જ યોગ જાણ. સ્વાર્થી સંકલ્પો છોડ્યા વિના કોઈ યોગી બનતું નથી.", null], "Gita 6.3": ["ગીતા 6.3", "6.3 · શ્રીકૃષ્ણ", "યોગ પર ચઢવા ઇચ્છતા મુનિ માટે કર્મને સાધન કહ્યું છે. યોગ પર ચઢી ગયા પછી તેના માટે જ શાંતિ (શમ)ને સાધન કહ્યું છે.", null], "Gita 6.4": ["ગીતા 6.4", "6.4 · શ્રીકૃષ્ણ", "જ્યારે વ્યક્તિ ન ઇન્દ્રિયોના વિષયોમાં આસક્ત થાય છે, ન કર્મોમાં, અને બધા સંકલ્પો છોડી દે છે, ત્યારે તેને યોગારૂઢ કહે છે.", null], "Gita 6.6": ["ગીતા 6.6", "6.6 · શ્રીકૃષ્ણ", "જેણે પોતાને જીતી લીધો છે, તેના માટે તેનું મન મિત્ર છે. જેણે નથી જીત્યો, તેના માટે એ જ મન શત્રુની જેમ વર્તે છે.", null], "Gita 6.7": ["ગીતા 6.7", "6.7 · શ્રીકૃષ્ણ", "જેણે પોતાને જીતી લીધો છે અને જે શાંત છે, તેનું મન ઠંડી-ગરમી, સુખ-દુઃખ અને માન-અપમાનમાં પણ પરમાત્મામાં સ્થિર રહે છે.", null], "Gita 6.8": ["ગીતા 6.8", "6.8 · શ્રીકૃષ્ણ", "જે જ્ઞાન અને અનુભવથી તૃપ્ત છે, અડગ છે, ઇન્દ્રિયોને જીતી ચૂક્યો છે, અને માટીના ઢેફા, પથ્થર અને સોનાને સમાન જુએ છે, તે યોગી યુક્ત કહેવાય છે.", null], "Gita 6.9": ["ગીતા 6.9", "6.9 · શ્રીકૃષ્ણ", "તેનાથી પણ શ્રેષ્ઠ તે છે જે શુભચિંતક, મિત્ર, શત્રુ, ઉદાસીન, મધ્યસ્થ, દ્વેષ કરનાર, સગાં, સજ્જન અને પાપી સૌમાં સમાન બુદ્ધિ રાખે છે.", null], "Gita 6.10": ["ગીતા 6.10", "6.10 · શ્રીકૃષ્ણ", "યોગી એકાંત સ્થાનમાં એકલો રહીને, મન અને શરીરને વશમાં રાખીને, આશા અને સંગ્રહ વિના, સતત મનને આત્મામાં લગાવે.", null], "Gita 6.11": ["ગીતા 6.11", "6.11 · શ્રીકૃષ્ણ", "શુદ્ધ સ્થાને પોતાનું સ્થિર આસન પાથરો, ન બહુ ઊંચું ન બહુ નીચું, જેના પર ક્રમશઃ દર્ભ, મૃગચર્મ અને કપડું પાથરેલું હોય.", null], "Gita 6.12": ["ગીતા 6.12", "6.12 · શ્રીકૃષ્ણ", "તેના પર બેસીને, મનને એકાગ્ર કરીને અને વિચારો તથા ઇન્દ્રિયોની ક્રિયાઓને વશમાં કરીને, આત્મ-શુદ્ધિ માટે યોગનો અભ્યાસ કરો.", null], "Gita 6.13": ["ગીતા 6.13", "6.13 · શ્રીકૃષ્ણ", "શરીર, માથું અને ગરદનને સીધાં અને અચળ રાખીને, સ્થિર થઈને, આમતેમ ન જોતાં પોતાની નાસિકાના અગ્રભાગ પર દૃષ્ટિ ટકાવો.", null], "Gita 6.14": ["ગીતા 6.14", "6.14 · શ્રીકૃષ્ણ", "શાંત અને નિર્ભય થઈને, બ્રહ્મચર્યના વ્રતમાં સ્થિર રહીને, મનને વશમાં કરીને, મારામાં ચિત્ત લગાવીને અને મને લક્ષ્ય માનીને બેસો.", null], "Gita 6.15": ["ગીતા 6.15", "6.15 · શ્રીકૃષ્ણ", "આ રીતે સદા અભ્યાસ કરતાં, મનને વશમાં રાખનાર યોગી મારામાં સ્થિત પરમ નિર્વાણ રૂપી શાંતિને પામે છે.", null], "Gita 6.16": ["ગીતા 6.16", "6.16 · શ્રીકૃષ્ણ", "હે અર્જુન, યોગ ન બહુ વધારે ખાનારનો સિદ્ધ થાય છે, ન બિલકુલ ન ખાનારનો, ન બહુ ઊંઘનારનો, ન બહુ જાગનારનો.", null], "Gita 6.18": ["ગીતા 6.18", "6.18 · શ્રીકૃષ્ણ", "જ્યારે વશમાં કરેલું ચિત્ત ફક્ત આત્મામાં સ્થિર થઈ જાય છે, અને બધી કામનાઓથી ઇચ્છા-રહિત થઈ જાય છે, ત્યારે તેને યોગયુક્ત કહે છે.", null], "Gita 6.19": ["ગીતા 6.19", "6.19 · શ્રીકૃષ્ણ", "\"જેમ પવન-રહિત સ્થાને મૂકેલો દીવો હાલતો નથી\": આ જ ઉપમા એ યોગી માટે અપાઈ છે જેનું ચિત્ત વશમાં છે અને જે ધ્યાનમાં લીન છે.", null], "Gita 6.20": ["ગીતા 6.20", "6.20 · શ્રીકૃષ્ણ", "જ્યારે યોગના અભ્યાસથી રોકાયેલું ચિત્ત શાંત થઈ જાય છે, અને વ્યક્તિ પોતાના દ્વારા આત્માને જોઈને આત્મામાં જ સંતુષ્ટ રહે છે,", null], "Gita 6.21": ["ગીતા 6.21", "6.21 · શ્રીકૃષ્ણ", "જ્યારે તે એ અનંત આનંદને જાણે છે જે બુદ્ધિથી ગ્રહણ થાય છે અને ઇન્દ્રિયોથી પર છે, અને તેમાં સ્થિત થઈને ફરી ક્યારેય સત્યથી ડગતો નથી,", null], "Gita 6.22": ["ગીતા 6.22", "6.22 · શ્રીકૃષ્ણ", "જેને પામીને તે બીજા કોઈ લાભને તેનાથી મોટો માનતો નથી, અને જેમાં સ્થિત થઈને મોટામાં મોટા દુઃખથી પણ વિચલિત થતો નથી,", null], "Gita 6.23": ["ગીતા 6.23", "6.23 · શ્રીકૃષ્ણ", "તેને જ યોગ જાણ: દુઃખના સંયોગમાંથી મુક્તિ. આ યોગનો અભ્યાસ દૃઢ નિશ્ચય સાથે અને નિરાશ થયા વિના કરવો જોઈએ.", null], "Gita 6.24": ["ગીતા 6.24", "6.24 · શ્રીકૃષ્ણ", "સ્વાર્થી સંકલ્પોમાંથી ઊઠતી બધી કામનાઓને પૂરેપૂરી છોડીને, અને મનથી જ ઇન્દ્રિયોના સમૂહને બધી બાજુથી રોકીને,", null], "Gita 6.25": ["ગીતા 6.25", "6.25 · શ્રીકૃષ્ણ", "ધીમે-ધીમે, ધીરજથી પકડેલી બુદ્ધિ સાથે શાંત થઈ જાઓ. મનને આત્મામાં સ્થિત કરીને બીજું કંઈ ન વિચારો.", null], "Gita 6.26": ["ગીતા 6.26", "6.26 · શ્રીકૃષ્ણ", "ચંચળ અને અસ્થિર મન જ્યાં-જ્યાં ભટકે, ત્યાં-ત્યાંથી તેને પાછું વાળીને આત્માના જ વશમાં લાવો.", null], "Gita 6.27": ["ગીતા 6.27", "6.27 · શ્રીકૃષ્ણ", "જેનું મન શાંત છે, જેની ચંચળતા (રજોગુણ) શાંત થઈ ગઈ છે, જે દોષ-રહિત છે અને બ્રહ્મ-રૂપ થઈ ગયો છે, એ યોગીને ઉત્તમ આનંદ મળે છે.", null], "Gita 6.28": ["ગીતા 6.28", "6.28 · શ્રીકૃષ્ણ", "આ રીતે સદા અભ્યાસ કરતાં, દોષ-રહિત યોગી સહજ જ બ્રહ્મના સ્પર્શ રૂપી અનંત આનંદનો અનુભવ કરે છે.", null], "Gita 6.29": ["ગીતા 6.29", "6.29 · શ્રીકૃષ્ણ", "યોગમાં સ્થિત વ્યક્તિ આત્માને સર્વ પ્રાણીઓમાં અને સર્વ પ્રાણીઓને આત્મામાં જુએ છે, અને સર્વત્ર સમાન જુએ છે.", null], "Gita 6.30": ["ગીતા 6.30", "6.30 · શ્રીકૃષ્ણ", "જે મને સર્વત્ર જુએ છે અને સૌને મારામાં જુએ છે, તેના માટે હું ક્યારેય ઓઝલ થતો નથી અને તે મારા માટે ક્યારેય ઓઝલ થતો નથી.", null], "Gita 6.31": ["ગીતા 6.31", "6.31 · શ્રીકૃષ્ણ", "જે યોગી એકત્વમાં સ્થિત થઈને મને સર્વ પ્રાણીઓમાં સ્થિત માનીને ભજે છે, તે ગમે તે રીતે રહે, મારામાં જ રહે છે.", null], "Gita 6.32": ["ગીતા 6.32", "6.32 · શ્રીકૃષ્ણ", "હે અર્જુન, જે પોતાના સમાન માનીને સૌનાં સુખ અને દુઃખને સમાન જુએ છે, તે પરમ યોગી મનાયો છે.", null], "Gita 6.33": ["ગીતા 6.33", "6.33 · અર્જુન", "અર્જુન બોલ્યા: હે મધુસૂદન, આપે જે સમતાનો યોગ કહ્યો, મનની ચંચળતાને કારણે હું તેની સ્થિર અવસ્થા જોઈ શકતો નથી.", null], "Gita 6.34": ["ગીતા 6.34", "6.34 · અર્જુન", "હે કૃષ્ણ, મન ચંચળ છે: ઉથલપાથલ કરનારું, બળવાન અને હઠીલું. તેને વશમાં કરવું મને વાયુને રોકવા જેટલું અઘરું લાગે છે.", null], "Gita 6.36": ["ગીતા 6.36", "6.36 · શ્રીકૃષ્ણ", "મારો મત છે કે જેનું મન વશમાં નથી, તેના માટે યોગ પામવો અઘરો છે. પણ જે સંયમી છે અને પ્રયાસ કરતો રહે છે, તે સાચા ઉપાયથી તેને પામી શકે છે.", null], "Gita 6.37": ["ગીતા 6.37", "6.37 · અર્જુન", "અર્જુન બોલ્યા: હે કૃષ્ણ, જે શ્રદ્ધા રાખે છે પણ પૂરો પ્રયાસ નથી કરતો, જેનું મન યોગમાંથી ભટકી જાય છે અને જે યોગની સિદ્ધિ પામતો નથી, તેની શી ગતિ થાય છે?", null], "Gita 6.38": ["ગીતા 6.38", "6.38 · અર્જુન", "હે મહાબાહો, શું તે બંને બાજુથી ભટકીને, આધાર વિના, બ્રહ્મના માર્ગમાં મોહિત થઈને વિખરાયેલા વાદળની જેમ નાશ પામતો નથી?", null], "Gita 6.39": ["ગીતા 6.39", "6.39 · અર્જુન", "હે કૃષ્ણ, મારા આ સંશયને પૂરેપૂરો મટાડી દો. આપના સિવાય આ સંશયને મટાડનાર કોઈ નથી.", null], "Gita 6.40": ["ગીતા 6.40", "6.40 · શ્રીકૃષ્ણ", "શ્રીકૃષ્ણ બોલ્યા: હે પાર્થ, આવી વ્યક્તિનો ન આ લોકમાં નાશ થાય છે, ન પરલોકમાં. હે તાત, ભલાઈ કરનાર કોઈ પણ દુર્ગતિને પામતો નથી.", null], "Gita 6.41": ["ગીતા 6.41", "6.41 · શ્રીકૃષ્ણ", "પુણ્ય કરનારાઓના લોકોમાં પહોંચીને અને ત્યાં ઘણાં વર્ષો સુધી રહીને, યોગમાંથી ભટકેલી વ્યક્તિ પવિત્ર અને સમૃદ્ધ લોકોના ઘરમાં જન્મ લે છે.", null], "Gita 6.42": ["ગીતા 6.42", "6.42 · શ્રીકૃષ્ણ", "કે પછી તે બુદ્ધિમાન યોગીઓના જ કુળમાં જન્મ લે છે. આવો જન્મ આ સંસારમાં ઘણો દુર્લભ છે.", null], "Gita 6.43": ["ગીતા 6.43", "6.43 · શ્રીકૃષ્ણ", "ત્યાં તેને પાછલા જન્મની બુદ્ધિ ફરી મળી જાય છે, અને હે કુરુનંદન, ત્યાંથી તે સિદ્ધિ માટે વધુ પ્રયાસ કરે છે.", null], "Gita 6.44": ["ગીતા 6.44", "6.44 · શ્રીકૃષ્ણ", "એ જ જૂના અભ્યાસથી તે ઇચ્છ્યા વિના પણ આગળ ખેંચાતો જાય છે. યોગને ફક્ત જાણવાની ઇચ્છા રાખનાર પણ વેદોના કર્મકાંડથી આગળ નીકળી જાય છે.", null], "Gita 6.45": ["ગીતા 6.45", "6.45 · શ્રીકૃષ્ણ", "પણ જે યોગી પ્રયત્નપૂર્વક સાધના કરે છે, દોષોથી શુદ્ધ થઈને અને અનેક જન્મોમાં સિદ્ધ થઈને, તે પરમ ગતિને પામે છે.", null], "Gita 6.46": ["ગીતા 6.46", "6.46 · શ્રીકૃષ્ણ", "યોગી તપસ્વીઓથી શ્રેષ્ઠ છે, જ્ઞાનીઓથી પણ શ્રેષ્ઠ મનાયો છે, અને કર્મકાંડ કરનારાઓથી પણ શ્રેષ્ઠ છે. તેથી હે અર્જુન, યોગી બન.", null], "Gita 6.47": ["ગીતા 6.47", "6.47 · શ્રીકૃષ્ણ", "અને બધા યોગીઓમાં પણ જે શ્રદ્ધાથી, પોતાના અંતર્મનને મારામાં લગાવીને મને ભજે છે, તેને હું સૌથી શ્રેષ્ઠ યોગી માનું છું.", null], "Katha Upanishad 2.3.11": ["કઠોપનિષદ 2.3.11", "ઇન્દ્રિયોને સ્થિર રાખવી એ યોગ છે", "ઇન્દ્રિયોની આ સ્થિર ધારણાને જ યોગ માનવામાં આવે છે. ત્યારે વ્યક્તિ સાવધ બને છે, કારણ કે યોગ આવે પણ છે અને જાય પણ છે.", "આ ઉપનિષદમાં યોગ શબ્દના સૌથી જૂના પ્રયોગોમાંનો એક છે: તેનો સંબંધ ઇન્દ્રિયો પરના અધિકાર સાથે છે, શરીરની લવચીકતા સાથે નહીં."], "Yoga Sutra 1.2": ["યોગસૂત્ર 1.2", "મનનાં તરંગોને શાંત કરવાં એ યોગ છે", "ચિત્તની વૃત્તિઓનો નિરોધ એ યોગ છે.", "એક સરોવરની કલ્પના કરો. પવન અટકતાં જ પાણી શાંત થઈ જાય છે અને તળિયું સાફ દેખાવા લાગે છે. પતંજલિ મન વિશે આ જ કહે છે."], "Yoga Sutra 2.29": ["યોગસૂત્ર 2.29", "યોગનાં આઠ અંગ", "યમ, નિયમ, આસન, પ્રાણાયામ, પ્રત્યાહાર, ધારણા, ધ્યાન અને સમાધિ, આ આઠ અંગ છે.", null], "Yoga Sutra 1.12": ["યોગસૂત્ર 1.12", "અભ્યાસ અને વૈરાગ્ય", "અભ્યાસ અને વૈરાગ્યથી ચિત્તવૃત્તિઓનો નિરોધ થાય છે.", "કૃષ્ણ પણ ગીતા 6.35માં આ જ કહે છે: મન ચંચળ છે, પણ અભ્યાસ અને વૈરાગ્યથી વશમાં આવે છે."], "Yoga Sutra 1.14": ["યોગસૂત્ર 1.14", "અભ્યાસ કેવી રીતે દૃઢ થાય છે", "અભ્યાસ લાંબા સમય સુધી, અટક્યા વગર અને શ્રદ્ધાથી કરવાથી દૃઢ થાય છે.", "રોજ દસ મિનિટ, મહિનામાં એક વાર બે કલાક કરતાં ઘણું વધારે કામ કરે છે."], "Yoga Sutra 1.33": ["યોગસૂત્ર 1.33", "નિર્મળ મનના ચાર ભાવ", "સુખી પ્રત્યે મૈત્રી, દુઃખી પ્રત્યે કરુણા, પુણ્યાત્મા પ્રત્યે પ્રસન્નતા અને પાપી પ્રત્યે ઉપેક્ષાનો ભાવ રાખવાથી ચિત્ત નિર્મળ થાય છે.", "મિત્રને ઇનામ મળે: ઈર્ષ્યા નહીં, ખુશી. કોઈ દુઃખી હોય: મદદ. કોઈ સારું કરે: પ્રશંસા. કોઈ તોછડું હોય: તેને મનમાં ન વસાવો."], "Yoga Sutra 2.46": ["યોગસૂત્ર 2.46", "સ્થિર અને સુખદ", "આસન સ્થિર અને સુખદ હોય.", "જો કોઈ આસન દુખાવો આપે કે જોર લગાડાવે, તો તે હજી તમારું આસન નથી. ઢીલું મૂકો."], "Charaka Samhita, Sutrasthana 30.26": ["ચરક સંહિતા, સૂત્રસ્થાન 30.26", "આયુર્વેદના બે ઉદ્દેશ", "તેનો ઉદ્દેશ છે સ્વસ્થ વ્યક્તિના સ્વાસ્થ્યની રક્ષા કરવી, અને રોગીના રોગને શાંત કરવો.", "ધ્યાન આપો કે સ્વસ્થ રહેવું પહેલાં આવે છે. આયુર્વેદનો મોટો ભાગ દિનચર્યા, ભોજન અને ઋતુઓ વિશે છે, દવાઓ વિશે નહીં."], "Sushruta Samhita, Sutrasthana 15": ["સુશ્રુત સંહિતા, સૂત્રસ્થાન 15", "ખરેખર સ્વસ્થ કોણ છે?", "જેના દોષ સમ હોય, અગ્નિ સમ હોય, ધાતુ અને મળની ક્રિયાઓ બરાબર હોય, અને જેનો આત્મા, ઇન્દ્રિયો અને મન પ્રસન્ન હોય, તે જ સ્વસ્થ કહેવાય છે.", "બે હજાર વર્ષ પહેલાં પણ સ્વાસ્થ્યનો અર્થ ફક્ત બરાબર કામ કરતું શરીર જ નહીં, પ્રસન્ન મન પણ હતો."], "Baudhayana Shulba Sutra": ["બૌધાયન શુલ્બસૂત્ર", "કર્ણનો નિયમ", "લંબચોરસનો કર્ણ એકલો જ એટલું ક્ષેત્રફળ બનાવે છે, જેટલું તેની બંને બાજુઓ અલગ-અલગ મળીને બનાવે છે.", "કર્ણ પર બનેલો ચોરસ બંને બાજુઓ પર બનેલા ચોરસોના સરવાળા જેટલો હોય છે: એ જ નિયમ જેને આજે પાયથાગોરસ પ્રમેય કહે છે."], "Aryabhatiya, Ganitapada 2": ["આર્યભટીય, ગણિતપાદ 2", "દરેક સ્થાન અગાઉનાથી દસ ગણું", "એક, દશ, શત, સહસ્ર, અયુત, નિયુત, પ્રયુત, કોટિ, અર્બુદ અને વૃંદ: એક સ્થાનથી બીજા સ્થાને દરેક અગાઉના કરતાં દસ ગણું હોય છે.", "આ જ દશાંશ સ્થાનમાનનો વિચાર છે, જેના પર આજે લખાતી દરેક સંખ્યા ટકી છે."], "Aryabhatiya, Ganitapada 10": ["આર્યભટીય, ગણિતપાદ 10", "ચાર દશાંશ સુધી પાઈ", "સોમાં ચાર ઉમેરો, આઠથી ગુણો, અને બાસઠ હજાર ઉમેરો: આ વીસ હજાર વ્યાસવાળા વર્તુળના પરિઘનું નજીકનું મૂલ્ય છે.", null], "Aryabhatiya, Golapada 9": ["આર્યભટીય, ગોલપાદ 9", "આકાશ નહીં, પૃથ્વી ફરે છે", "જેમ આગળ વધતી હોડીમાં બેઠેલો માણસ કિનારાની સ્થિર વસ્તુઓને પાછળ જતી જુએ છે, તેમ લંકા (વિષુવવૃત્ત) પર સ્થિર તારા સીધા પશ્ચિમ તરફ જતા દેખાય છે.", "તારા ફક્ત ચાલતા દેખાય છે, કારણ કે પૃથ્વી પોતે ફરે છે."]};